// Atlas de Mary, segunda parte: órganos, sistema nervioso central, arterias, venas y nervios.
// atlas.js llama a addSistemas(add) después de sus propias entradas para no cambiar los ids numéricos
// (sid) ya horneados. Los ids de texto son fijos porque la geometría 3D los usa.
// Enlaces: n = nervios, a = arterias, v = venas (ids del atlas).

export function addSistemas(add) {
  // ============================ ÓRGANOS ============================
  add('organo', 'corazon', 'Corazón', 'Bomba muscular hueca, del tamaño de un puño, situada en el centro del tórax entre los pulmones y desviada hacia la izquierda. Sus cuatro cavidades (dos aurículas y dos ventrículos) impulsan la sangre hacia los pulmones y hacia todo el cuerpo.', { irrig: 'Arterias coronarias derecha e izquierda, las primeras ramas de la aorta.', drenaje: 'Sobre todo por las venas cardíacas, que se reúnen en el seno coronario y desembocan en la aurícula derecha.', inerv: 'Plexo cardíaco: los nervios simpáticos (de los segmentos torácicos altos) lo aceleran y el nervio vago lo enlentece. Cada latido se origina en su propio marcapasos, el nódulo sinusal.', clinica: 'La obstrucción de una arteria coronaria causa el infarto de miocardio; su dolor opresivo en el pecho suele irradiarse al brazo izquierdo, al cuello o a la mandíbula.', a: ['a_coronarias', 'aorta', 'a_pulmonar'], v: ['v_cava_superior', 'v_cava_inferior', 'v_pulmonares'], n: ['n_vago', 'tronco_simpatico'] });
  add('organo', 'pulmon_der', 'Pulmón derecho', 'Órgano esponjoso donde la sangre toma oxígeno y elimina dióxido de carbono. Tiene tres lóbulos (superior, medio e inferior) y es más corto y ancho que el izquierdo porque el hígado eleva el diafragma de ese lado.', { irrig: 'La arteria pulmonar derecha le trae la sangre que debe oxigenarse; las arterias bronquiales nutren el propio tejido del pulmón.', drenaje: 'Venas pulmonares derechas (superior e inferior), que llevan la sangre oxigenada a la aurícula izquierda; las venas bronquiales van a la vena ácigos.', inerv: 'Plexo pulmonar: el nervio vago contrae los bronquios y aumenta el moco; los nervios simpáticos los dilatan.', clinica: 'El bronquio principal derecho es más ancho, corto y vertical que el izquierdo; por eso los objetos aspirados suelen ir a este pulmón.', a: ['a_pulmonar', 'aorta'], v: ['v_pulmonares', 'v_acigos'], n: ['n_vago', 'tronco_simpatico'] });
  add('organo', 'pulmon_izq', 'Pulmón izquierdo', 'Pulmón de dos lóbulos (superior e inferior), algo más pequeño que el derecho porque deja espacio al corazón. Su borde anterior tiene una escotadura cardíaca y, debajo de ella, una lengüeta llamada língula.', { irrig: 'La arteria pulmonar izquierda le trae la sangre que debe oxigenarse; dos arterias bronquiales, ramas de la aorta torácica, nutren su tejido.', drenaje: 'Venas pulmonares izquierdas (superior e inferior) hacia la aurícula izquierda; las venas bronquiales van al sistema ácigos (vena hemiácigos accesoria).', inerv: 'Plexo pulmonar, formado por el nervio vago (contrae los bronquios) y por nervios simpáticos (los dilatan).', clinica: 'Si entra aire entre las pleuras (neumotórax), el pulmón se colapsa y aparecen de forma súbita dolor en el pecho y falta de aire.', a: ['a_pulmonar', 'aorta'], v: ['v_pulmonares', 'v_acigos'], n: ['n_vago', 'tronco_simpatico'] });
  add('organo', 'traquea', 'Tráquea y bronquios', 'Tubo de unos 10 cm, reforzado por 16 a 20 anillos de cartílago en forma de C, que lleva el aire de la laringe a los pulmones. A la altura del ángulo esternal (T4–T5) se divide en los dos bronquios principales, que se ramifican dentro de cada pulmón.', { irrig: 'Arterias tiroideas inferiores en el cuello y arterias bronquiales en el tórax.', drenaje: 'Venas tiroideas inferiores, que van a las venas braquiocefálicas, y venas bronquiales.', inerv: 'Nervio vago y sus ramos laríngeos recurrentes, con fibras del tronco simpático.', clinica: 'La traqueostomía es una abertura quirúrgica en su parte del cuello, por debajo del cartílago cricoides, para asegurar la respiración.', a: ['a_subclavia', 'aorta'], v: ['v_braquiocefalica'], n: ['n_vago', 'tronco_simpatico'] });
  add('organo', 'laringe', 'Laringe', 'Órgano de la voz, en la parte anterior del cuello, formado por cartílagos (tiroides, cricoides, aritenoides y epiglotis) unidos por músculos y ligamentos. Contiene las cuerdas vocales y protege la vía aérea al tragar.', { irrig: 'Arterias laríngeas superior (de la tiroidea superior, rama de la carótida externa) e inferior (de la tiroidea inferior, rama de la subclavia).', drenaje: 'Venas laríngeas, que drenan en las venas tiroideas y de ahí en la yugular interna y la braquiocefálica izquierda.', inerv: 'Ramas del nervio vago: el laríngeo superior (sensibilidad por encima de las cuerdas vocales y músculo cricotiroideo) y el laríngeo recurrente (los demás músculos y la sensibilidad por debajo de las cuerdas).', clinica: 'La lesión de un nervio laríngeo recurrente, por ejemplo en una cirugía de tiroides, paraliza una cuerda vocal y deja la voz ronca.', a: ['a_carotida_externa', 'a_subclavia'], v: ['v_yugular_interna', 'v_braquiocefalica'], n: ['n_vago'] });
  add('organo', 'tiroides', 'Glándula tiroides', 'Glándula endocrina en forma de mariposa situada delante de la tráquea, debajo del cartílago tiroides: dos lóbulos unidos por un istmo. Produce las hormonas tiroideas, que regulan el metabolismo, y la calcitonina.', { irrig: 'Arterias tiroideas superiores (de la carótida externa) e inferiores (del tronco tirocervical de la subclavia).', drenaje: 'Venas tiroideas superior y media hacia la yugular interna, e inferior hacia las venas braquiocefálicas.', inerv: 'Fibras simpáticas de los ganglios cervicales, que regulan sus vasos; su secreción la controla sobre todo la hormona TSH de la hipófisis.', clinica: 'Su aumento de tamaño se llama bocio; la falta de yodo en la dieta es su causa clásica.', a: ['a_carotida_externa', 'a_subclavia'], v: ['v_yugular_interna', 'v_braquiocefalica'], n: ['tronco_simpatico', 'n_vago'] });
  add('organo', 'esofago', 'Esófago', 'Tubo muscular de unos 25 cm que lleva el alimento de la faringe al estómago, por detrás de la tráquea y del corazón. Atraviesa el diafragma a la altura de T10 y empuja el bolo con ondas de contracción (peristaltismo).', { irrig: 'Arterias tiroideas inferiores (cuello), ramas esofágicas de la aorta torácica (tórax) y arteria gástrica izquierda (abdomen).', drenaje: 'Venas tiroideas inferiores, sistema ácigos y, en su parte abdominal, la vena gástrica izquierda, que va a la vena porta.', inerv: 'Nervios vagos, que forman el plexo esofágico, y fibras simpáticas. Su tercio superior tiene músculo estriado y el inferior, músculo liso.', clinica: 'En la hipertensión portal sus venas inferiores se dilatan (várices esofágicas) y pueden sangrar de forma grave.', a: ['a_subclavia', 'aorta', 'tronco_celiaco'], v: ['v_acigos', 'v_porta'], n: ['n_vago', 'tronco_simpatico'] });
  add('organo', 'higado', 'Hígado', 'La glándula más grande del cuerpo, situada bajo el diafragma en la parte superior derecha del abdomen. Produce la bilis, almacena energía como glucógeno, fabrica proteínas de la sangre y elimina tóxicos y medicamentos.', { irrig: 'Doble: la vena porta aporta el 75–80 % de su sangre (rica en nutrientes del intestino) y la arteria hepática el 20–25 % (rica en oxígeno).', drenaje: 'Venas hepáticas (derecha, media e izquierda), que desembocan en la vena cava inferior justo debajo del diafragma.', inerv: 'Plexo hepático, con fibras simpáticas del plexo celíaco y parasimpáticas del nervio vago; su cápsula duele cuando se estira.', clinica: 'El consumo excesivo de alcohol y las hepatitis virales pueden causar cirrosis, en la que el tejido sano se reemplaza por cicatrices.', a: ['a_hepatica', 'tronco_celiaco'], v: ['v_porta', 'v_hepaticas', 'v_cava_inferior'], n: ['n_vago', 'tronco_simpatico'] });
  add('organo', 'vesicula', 'Vesícula biliar', 'Bolsa en forma de pera, bajo el hígado, que almacena y concentra la bilis. Al comer alimentos grasos se contrae y la vacía por los conductos cístico y colédoco hacia el duodeno.', { irrig: 'Arteria cística, casi siempre rama de la arteria hepática derecha.', drenaje: 'Venas císticas, que entran directamente en el hígado o en la vena porta.', inerv: 'Plexo celíaco (fibras simpáticas y de dolor), nervio vago y nervio frénico derecho, que lleva la sensibilidad del peritoneo que la cubre.', clinica: 'Los cálculos biliares pueden inflamarla (colecistitis): el dolor aparece bajo las costillas derechas y puede irradiarse al hombro derecho.', a: ['a_hepatica'], v: ['v_porta'], n: ['n_vago', 'n_frenico', 'tronco_simpatico'] });
  add('organo', 'estomago', 'Estómago', 'Saco muscular en forma de J, en la parte superior izquierda del abdomen, entre el esófago y el duodeno. Mezcla los alimentos con jugo gástrico ácido y enzimas y los vacía poco a poco a través del píloro.', { irrig: 'Ramas del tronco celíaco: arterias gástricas izquierda y derecha (curvatura menor), gastroomentales (curvatura mayor) y gástricas cortas (fondo).', drenaje: 'Venas gástricas y gastroomentales, que desembocan en la vena porta o en sus afluentes (esplénica y mesentérica superior).', inerv: 'El nervio vago estimula la secreción de ácido y los movimientos; los nervios simpáticos del plexo celíaco los frenan y conducen el dolor.', clinica: 'La bacteria Helicobacter pylori y los antiinflamatorios no esteroideos (como el ibuprofeno) son las principales causas de úlcera gástrica.', a: ['tronco_celiaco', 'a_hepatica', 'a_esplenica'], v: ['v_porta'], n: ['n_vago', 'tronco_simpatico'] });
  add('organo', 'bazo', 'Bazo', 'Órgano blando, del tamaño de un puño, en la parte superior izquierda del abdomen, protegido por las costillas 9 a 11. Filtra la sangre, retira los glóbulos rojos viejos y ayuda a defender al cuerpo de las infecciones.', { irrig: 'Arteria esplénica, la rama más grande del tronco celíaco.', drenaje: 'Vena esplénica, que se une a la mesentérica superior detrás del páncreas para formar la vena porta.', inerv: 'Plexo esplénico, derivado del plexo celíaco (fibras sobre todo simpáticas que regulan sus vasos).', clinica: 'Es uno de los órganos que más se lesionan en los golpes al abdomen; su rotura causa una hemorragia interna grave.', a: ['a_esplenica', 'tronco_celiaco'], v: ['v_porta'], n: ['tronco_simpatico'] });
  add('organo', 'pancreas', 'Páncreas', 'Glándula alargada detrás del estómago, con cabeza (rodeada por el duodeno), cuerpo y cola (que llega al bazo). Vierte jugos digestivos al duodeno y produce hormonas como la insulina y el glucagón, que controlan el azúcar en la sangre.', { irrig: 'Arterias pancreaticoduodenales (de la gastroduodenal y de la mesentérica superior) y ramas pancreáticas de la arteria esplénica.', drenaje: 'Venas pancreáticas y pancreaticoduodenales, hacia las venas esplénica y mesentérica superior, que forman la vena porta.', inerv: 'Nervio vago (estimula la secreción) y nervios esplácnicos simpáticos, que llegan por los plexos celíaco y mesentérico superior.', clinica: 'La pancreatitis aguda, causada sobre todo por cálculos biliares o por alcohol, produce un dolor intenso en la parte alta del abdomen que se irradia a la espalda.', a: ['a_esplenica', 'a_hepatica', 'a_mesenterica_superior'], v: ['v_porta'], n: ['n_vago', 'tronco_simpatico'] });
  add('organo', 'duodeno', 'Duodeno', 'Primera parte del intestino delgado, de unos 25 cm, en forma de C alrededor de la cabeza del páncreas. En él desembocan la bilis y el jugo pancreático, que continúan la digestión.', { irrig: 'Arterias pancreaticoduodenales superiores (de la gastroduodenal, que viene del tronco celíaco) e inferiores (de la mesentérica superior).', drenaje: 'Venas pancreaticoduodenales, que van a la vena porta y a la mesentérica superior.', inerv: 'Nervio vago y nervios simpáticos de los plexos celíaco y mesentérico superior.', clinica: 'Es el sitio más frecuente de las úlceras pépticas, casi siempre en su primera porción (bulbo duodenal).', a: ['tronco_celiaco', 'a_hepatica', 'a_mesenterica_superior'], v: ['v_porta'], n: ['n_vago', 'tronco_simpatico'] });
  add('organo', 'intestino_delgado', 'Intestino delgado (yeyuno e íleon)', 'El tramo más largo del tubo digestivo: el yeyuno y el íleon miden juntos unos 6 a 7 m y cuelgan del mesenterio en el centro del abdomen. Aquí se completa la digestión y se absorbe la mayor parte de los nutrientes.', { irrig: 'Arterias yeyunales e ileales, ramas de la mesentérica superior que forman arcadas dentro del mesenterio.', drenaje: 'Venas yeyunales e ileales, que van a la vena mesentérica superior y de ahí a la vena porta.', inerv: 'Plexo mesentérico superior: el nervio vago aumenta los movimientos y las secreciones y los nervios simpáticos los disminuyen.', clinica: 'La parte final del íleon absorbe la vitamina B12; si se extirpa o se enferma (por ejemplo, en la enfermedad de Crohn) puede aparecer anemia.', a: ['a_mesenterica_superior'], v: ['v_porta'], n: ['n_vago', 'tronco_simpatico'] });
  add('organo', 'colon', 'Intestino grueso (colon)', 'Parte principal del intestino grueso, que enmarca al intestino delgado: ciego, colon ascendente, transverso, descendente y sigmoide. Absorbe agua y sales y convierte los restos de la digestión en heces.', { irrig: 'Arteria mesentérica superior (ciego, colon ascendente y dos tercios del transverso) y mesentérica inferior (el resto, hasta el sigmoide).', drenaje: 'Venas mesentéricas superior e inferior, que llevan la sangre a la vena porta.', inerv: 'Nervio vago hasta los dos tercios del colon transverso y nervios esplácnicos pélvicos (S2–S4) desde allí; fibras simpáticas de los plexos mesentéricos.', clinica: 'La colonoscopia permite encontrar y quitar pólipos antes de que se conviertan en cáncer de colon.', a: ['a_mesenterica_superior', 'a_mesenterica_inferior'], v: ['v_porta'], n: ['n_vago', 'tronco_simpatico'] });
  add('organo', 'apendice', 'Apéndice', 'Tubo estrecho y cerrado en un extremo, de unos 6 a 10 cm, que sale del ciego en la parte baja derecha del abdomen. Contiene abundante tejido linfoide.', { irrig: 'Arteria apendicular, rama de la arteria ileocólica (de la mesentérica superior).', drenaje: 'Vena apendicular, que va a la ileocólica y a la mesentérica superior, hacia la vena porta.', inerv: 'Fibras simpáticas y del nervio vago del plexo mesentérico superior; su dolor entra en la médula por el segmento T10.', clinica: 'En la apendicitis el dolor suele empezar alrededor del ombligo y después se fija en la fosa ilíaca derecha (punto de McBurney).', a: ['a_mesenterica_superior'], v: ['v_porta'], n: ['n_vago', 'tronco_simpatico'] });
  add('organo', 'recto', 'Recto y conducto anal', 'Parte final del tubo digestivo: el recto almacena las heces y el conducto anal, de unos 4 cm, termina en el ano. Lo cierran los esfínteres anales interno (involuntario) y externo (voluntario).', { irrig: 'Arteria rectal superior (de la mesentérica inferior) y arterias rectales media e inferior (de la ilíaca interna y de su rama pudenda interna).', drenaje: 'La vena rectal superior va a la vena porta (por la mesentérica inferior); las rectales media e inferior van a la vena cava inferior a través de la ilíaca interna.', inerv: 'Nervios esplácnicos pélvicos (S2–S4) y fibras simpáticas; el esfínter externo y la piel del ano reciben el nervio rectal inferior, rama del pudendo.', clinica: 'Las hemorroides son dilataciones de sus plexos venosos; las internas no duelen porque están por encima de la línea pectínea, donde no hay nervios de dolor somático.', a: ['a_mesenterica_inferior', 'a_iliaca_interna'], v: ['v_porta', 'v_iliaca_interna'], n: ['plexo_sacro', 'tronco_simpatico'] });
  add('organo', 'rinones', 'Riñones', 'Dos órganos en forma de frijol, detrás del peritoneo a los lados de la columna (de T12 a L3); el derecho queda algo más bajo por el hígado. Filtran la sangre para formar la orina y regulan el agua, las sales y la presión arterial.', { irrig: 'Arterias renales, ramas directas de la aorta abdominal; reciben cerca de una quinta parte de toda la sangre que bombea el corazón.', drenaje: 'Venas renales, hacia la vena cava inferior; la izquierda, más larga, cruza por delante de la aorta.', inerv: 'Plexo renal, con fibras simpáticas de los nervios esplácnicos que regulan sus vasos; el dolor renal se siente en el flanco y en la espalda baja.', clinica: 'Un cálculo que baja por el uréter causa el cólico renal: un dolor muy intenso que va de la espalda hacia la ingle.', a: ['a_renal', 'aorta_abdominal'], v: ['v_renal', 'v_cava_inferior'], n: ['tronco_simpatico'] });
  add('organo', 'suprarrenales', 'Glándulas suprarrenales', 'Dos glándulas endocrinas pequeñas sobre el polo superior de cada riñón; la derecha es triangular y la izquierda tiene forma de media luna. Su corteza produce cortisol y aldosterona, y su médula, adrenalina y noradrenalina.', { irrig: 'Tres grupos de arterias suprarrenales a cada lado: superiores (de la frénica inferior), media (de la aorta) e inferior (de la renal).', drenaje: 'Una vena suprarrenal por lado: la derecha va directamente a la cava inferior y la izquierda a la vena renal izquierda.', inerv: 'Fibras simpáticas de los nervios esplácnicos que llegan directamente a la médula, la cual funciona como un ganglio simpático.', clinica: 'La falta de hormonas de su corteza (enfermedad de Addison) causa cansancio, presión baja y oscurecimiento de la piel.', a: ['aorta_abdominal', 'a_renal'], v: ['v_cava_inferior', 'v_renal'], n: ['tronco_simpatico'] });
  add('organo', 'ureteres', 'Uréteres', 'Dos conductos musculares de 25 a 30 cm que llevan la orina de cada riñón a la vejiga mediante ondas de contracción. Bajan por detrás del peritoneo, sobre el músculo psoas, y cruzan los vasos ilíacos al entrar en la pelvis.', { irrig: 'Ramas de las arterias renales, gonadales, aorta abdominal, ilíacas comunes e internas y vesicales, según el tramo.', drenaje: 'Venas que acompañan a esas arterias, hacia las venas renales, gonadales e ilíacas internas.', inerv: 'Plexos renal, aórtico e hipogástrico; sus fibras de dolor entran en la médula entre T11 y L2.', clinica: 'Los cálculos se atascan en sus tres estrechamientos: a la salida del riñón, al cruzar los vasos ilíacos y al entrar en la vejiga.', a: ['a_renal', 'aorta_abdominal', 'a_iliaca_comun', 'a_iliaca_interna'], v: ['v_renal', 'v_iliaca_interna'], n: ['tronco_simpatico'] });
  add('organo', 'vejiga', 'Vejiga urinaria', 'Bolsa muscular hueca en la pelvis, detrás del pubis, que almacena la orina hasta que se vacía por la uretra. Su pared es el músculo detrusor, que se contrae al orinar.', { irrig: 'Arterias vesicales superiores e inferiores, ramas de la ilíaca interna (en la mujer, las vaginales reemplazan a las vesicales inferiores).', drenaje: 'Plexo venoso vesical, que drena en las venas ilíacas internas.', inerv: 'Los nervios esplácnicos pélvicos (parasimpáticos, S2–S4) contraen el detrusor para vaciarla; las fibras simpáticas vienen de T11–L2. El esfínter externo de la uretra, voluntario, depende del nervio pudendo.', clinica: 'Las infecciones urinarias son más frecuentes en la mujer porque su uretra es mucho más corta.', a: ['a_iliaca_interna'], v: ['v_iliaca_interna'], n: ['plexo_sacro', 'tronco_simpatico'] });
  add('organo', 'ojos', 'Globos oculares', 'Órganos de la vista, alojados en las órbitas: esferas de unos 2,4 cm de diámetro con córnea, iris, cristalino y retina. La córnea y el cristalino enfocan la luz sobre la retina, que la convierte en impulsos nerviosos.', { irrig: 'Arteria oftálmica, primera rama de la carótida interna dentro del cráneo; su rama, la arteria central de la retina, nutre las capas internas de la retina.', drenaje: 'Venas oftálmicas, que drenan en el seno cavernoso; la vena central de la retina sigue el mismo camino.', inerv: 'Nervio óptico (visión); oculomotor, troclear y abducens (músculos que mueven el ojo); trigémino (sensibilidad de la córnea).', clinica: 'El glaucoma daña poco a poco el nervio óptico, a menudo por aumento de la presión dentro del ojo; sin tratamiento puede causar ceguera.', a: ['a_carotida_interna'], v: ['senos_venosos'], n: ['n_optico', 'n_trigemino'] });

  // ============================ SISTEMA NERVIOSO CENTRAL ============================
  add('snc', 'encefalo', 'Cerebro (hemisferios cerebrales)', 'La parte más grande del encéfalo: dos hemisferios unidos por el cuerpo calloso, con una corteza plegada en circunvoluciones y dividida en lóbulos frontal, parietal, temporal, occipital e ínsula. Controla el movimiento voluntario, la sensibilidad, el lenguaje, la visión, la memoria y el pensamiento.', { irrig: 'Arterias carótidas internas y vertebrales, unidas en la base del cerebro por el polígono de Willis, del que salen las arterias cerebrales anterior, media y posterior.', drenaje: 'Venas cerebrales que desembocan en los senos venosos de la duramadre y de ahí en las venas yugulares internas.', inerv: 'El tejido cerebral no tiene receptores de dolor; la duramadre que lo envuelve recibe sobre todo ramos del trigémino. A él llegan directamente los nervios olfatorio (I) y óptico (II).', clinica: 'Cada hemisferio controla la mitad opuesta del cuerpo: un accidente cerebrovascular en el hemisferio izquierdo paraliza el lado derecho.', a: ['a_cerebrales', 'a_carotida_interna', 'a_vertebral'], v: ['senos_venosos', 'v_yugular_interna'], n: ['n_optico', 'n_trigemino'] });
  add('snc', 'cerebelo', 'Cerebelo', 'Órgano situado en la parte posterior e inferior del cráneo, detrás del tronco encefálico y debajo de los lóbulos occipitales. Coordina los movimientos, el equilibrio y la postura, y participa en el aprendizaje de habilidades motoras.', { irrig: 'Arterias cerebelosas superior, anteroinferior y posteroinferior, ramas de las arterias vertebrales y basilar.', drenaje: 'Venas cerebelosas, que drenan en los senos venosos vecinos (recto, transversos y petrosos).', inerv: 'Se comunica con el tronco encefálico por tres pares de pedúnculos cerebelosos, por los que recibe información de la médula, del oído interno (equilibrio) y de la corteza cerebral.', clinica: 'Su lesión (o el exceso de alcohol) causa ataxia: marcha tambaleante, movimientos torpes y temblor al intentar alcanzar un objeto.', a: ['a_vertebral'], v: ['senos_venosos'] });
  add('snc', 'tronco_encefalico', 'Tronco encefálico', 'Tallo que une el cerebro con la médula espinal, formado por mesencéfalo, puente (protuberancia) y bulbo raquídeo. Contiene los centros que controlan la respiración, el ritmo cardíaco y el estado de alerta, y por él pasan las vías que comunican el cerebro con el cuerpo.', { irrig: 'Arterias vertebrales y basilar y sus ramas (cerebelosas y pontinas); el mesencéfalo recibe además ramas de la cerebral posterior.', drenaje: 'Pequeñas venas que drenan en los senos venosos de la base del cráneo y, de ahí, en las yugulares internas.', inerv: 'De él salen 10 de los 12 pares craneales (del III al XII), que mueven y dan sensibilidad a la cabeza y el cuello y, por el vago, regulan las vísceras.', clinica: 'Una lesión del bulbo raquídeo puede ser mortal, porque allí están los centros que mantienen la respiración y la circulación.', a: ['a_vertebral', 'a_cerebrales'], v: ['senos_venosos'], n: ['n_trigemino', 'n_facial', 'n_vago', 'n_accesorio'] });
  add('snc', 'medula', 'Médula espinal', 'Cordón nervioso de unos 42 a 45 cm que baja por el conducto vertebral desde el bulbo raquídeo hasta la altura de L1–L2. Conduce los mensajes entre el encéfalo y el cuerpo y coordina reflejos como el rotuliano.', { irrig: 'Una arteria espinal anterior y dos posteriores (ramas de las vertebrales), reforzadas por arterias segmentarias; la más importante es la radicular magna (de Adamkiewicz).', drenaje: 'Venas espinales que drenan en los plexos venosos vertebrales y de ahí en las venas segmentarias y el sistema ácigos.', inerv: 'De ella salen 31 pares de nervios raquídeos, cada uno formado por una raíz anterior (motora) y una posterior (sensitiva).', clinica: 'Una lesión completa de la médula causa parálisis y pérdida de la sensibilidad por debajo del nivel dañado: paraplejia si es torácica o lumbar, tetraplejia si es cervical.', a: ['a_vertebral', 'a_intercostales', 'aorta'], v: ['v_acigos'], n: ['nervios_raquideos', 'tronco_simpatico'] });
  add('snc', 'cola_caballo', 'Cola de caballo', 'Haz de raíces nerviosas lumbares, sacras y coccígeas que bajan por el conducto vertebral por debajo del final de la médula (L1–L2), con aspecto de cola de caballo. Flotan en el líquido cefalorraquídeo hasta salir por sus agujeros intervertebrales y sacros.', { irrig: 'Arterias radiculares que acompañan a cada raíz, ramas de las arterias lumbares y sacras laterales.', drenaje: 'Venas radiculares, que drenan en los plexos venosos vertebrales internos.', inerv: 'Sus raíces forman los nervios de las piernas, la vejiga, el recto y los genitales.', clinica: 'La punción lumbar se hace entre L3 y L4 o entre L4 y L5 porque ahí ya no hay médula y las raíces flotantes se apartan de la aguja.', a: ['aorta_abdominal', 'a_iliaca_interna'], n: ['nervios_raquideos', 'plexo_lumbar', 'plexo_sacro'] });

  // ============================ ARTERIAS ============================
  add('arteria', 'aorta', 'Aorta torácica', 'La arteria más grande del cuerpo: sale del corazón y distribuye sangre rica en oxígeno a todo el organismo. En el tórax tiene tres partes: aorta ascendente, arco (cayado) y aorta descendente.', { nace: 'Ventrículo izquierdo, a través de la válvula aórtica.', recorrido: 'Sube unos 5 cm, forma un arco hacia atrás y a la izquierda por detrás del manubrio del esternón y baja por el lado izquierdo de la columna torácica hasta atravesar el diafragma por el hiato aórtico (T12).', irriga: 'La parte ascendente da las coronarias; el arco, el tronco braquiocefálico, la carótida común izquierda y la subclavia izquierda; la descendente, arterias intercostales, bronquiales y esofágicas.', clinica: 'La disección de la aorta (desgarro de su capa interna) causa un dolor torácico súbito y desgarrador que suele irradiarse a la espalda; es una urgencia vital.', v: ['v_acigos'], n: ['n_vago', 'n_frenico'] });
  add('arteria', 'aorta_abdominal', 'Aorta abdominal', 'Continuación de la aorta por debajo del diafragma; baja por delante de la columna lumbar y reparte la sangre a las vísceras del abdomen, a su pared y a las piernas.', { nace: 'Es la continuación de la aorta torácica al pasar por el hiato aórtico del diafragma, a la altura de T12.', recorrido: 'Desciende por delante de los cuerpos vertebrales, algo a la izquierda de la línea media y junto a la vena cava inferior, y se divide en las dos ilíacas comunes a la altura de L4, cerca del ombligo.', irriga: 'Tres ramas impares para el tubo digestivo (tronco celíaco y mesentéricas superior e inferior), ramas pares para suprarrenales, riñones y gónadas, y arterias frénicas inferiores y lumbares.', clinica: 'Un aneurisma (dilatación) de la aorta abdominal puede palparse como una masa que late cerca del ombligo; si se rompe, es una emergencia mortal.', v: ['v_cava_inferior'], n: ['tronco_simpatico'] });
  add('arteria', 'tronco_braquiocefalico', 'Tronco braquiocefálico', 'La primera y más grande rama del arco aórtico; solo existe en el lado derecho.', { nace: 'Arco de la aorta, por detrás del manubrio del esternón.', recorrido: 'Sube hacia la derecha por delante de la tráquea y, detrás de la articulación esternoclavicular derecha, se divide en carótida común derecha y subclavia derecha.', irriga: 'Por sus dos ramas, el lado derecho de la cabeza y el cuello y el miembro superior derecho.', clinica: 'Cruza por delante de la tráquea; una traqueostomía demasiado baja puede lesionarlo y causar un sangrado grave.', v: ['v_braquiocefalica'] });
  add('arteria', 'a_carotida_comun', 'Arteria carótida común', 'Arteria principal del cuello, una a cada lado, que lleva la sangre hacia la cabeza.', { nace: 'La derecha, del tronco braquiocefálico; la izquierda, directamente del arco aórtico.', recorrido: 'Sube por el cuello dentro de la vaina carotídea, junto a la vena yugular interna y el nervio vago, cubierta por el esternocleidomastoideo; sin dar ramas, se divide en carótida interna y externa a la altura del borde superior del cartílago tiroides (C4).', irriga: 'A través de sus dos ramas, el encéfalo, el ojo, la cara, el cuero cabelludo y el cuello.', clinica: 'Su pulso se palpa a un lado de la tráquea, en el borde anterior del esternocleidomastoideo; es el pulso que se busca en una emergencia.', v: ['v_yugular_interna'], n: ['n_vago'] });
  add('arteria', 'a_carotida_interna', 'Arteria carótida interna', 'Rama de la carótida común que entra en el cráneo sin dar ramas en el cuello e irriga la mayor parte del cerebro y el ojo.', { nace: 'Bifurcación de la carótida común, a la altura del borde superior del cartílago tiroides (C4).', recorrido: 'Sube por el cuello dentro de la vaina carotídea, entra en el cráneo por el conducto carotídeo del hueso temporal, atraviesa el seno cavernoso y termina dividiéndose en arterias cerebrales anterior y media.', irriga: 'Hemisferios cerebrales (por las cerebrales anterior y media) y el ojo y la órbita (por la arteria oftálmica).', clinica: 'Las placas de ateroma en su origen son una causa frecuente de accidente cerebrovascular; se detectan con una ecografía Doppler del cuello.', v: ['v_yugular_interna', 'senos_venosos'], n: ['n_vago'] });
  add('arteria', 'a_carotida_externa', 'Arteria carótida externa', 'Rama de la carótida común que irriga la cara, el cuello, la boca, el cuero cabelludo y, por la arteria meníngea media, las meninges.', { nace: 'Bifurcación de la carótida común, a la altura del borde superior del cartílago tiroides (C4).', recorrido: 'Sube por delante de la carótida interna, entra en la glándula parótida y, detrás del cuello de la mandíbula, termina dividiéndose en arterias maxilar y temporal superficial.', irriga: 'Por sus ocho ramas (tiroidea superior, lingual, facial, faríngea ascendente, occipital, auricular posterior, maxilar y temporal superficial): tiroides, laringe, lengua, cara, dientes, cuero cabelludo y meninges.', clinica: 'Se puede ligar para detener una hemorragia grave de una de sus ramas, porque la sangre sigue llegando por anastomosis con la del lado opuesto.', n: ['n_facial'] });
  add('arteria', 'a_facial', 'Arteria facial', 'Rama de la carótida externa que irriga los tejidos superficiales de la cara.', { nace: 'Carótida externa, justo por encima de la arteria lingual (a veces en un tronco común con ella).', recorrido: 'Pasa por la glándula submandibular, cruza el borde inferior de la mandíbula por delante del masetero y sube, muy sinuosa, junto a la nariz hasta el ángulo del ojo, donde se llama arteria angular.', irriga: 'Glándula submandibular, labios (arterias labiales), lado de la nariz y músculos de la cara; se comunica con ramas de la arteria oftálmica.', clinica: 'Su pulso se palpa donde cruza el borde de la mandíbula, justo por delante del músculo masetero.', v: ['v_facial'], n: ['n_facial'] });
  add('arteria', 'a_temporal_superficial', 'Arteria temporal superficial', 'La rama terminal más pequeña de la carótida externa; irriga la sien y el cuero cabelludo.', { nace: 'Carótida externa, dentro de la glándula parótida, por detrás del cuello de la mandíbula.', recorrido: 'Sube por delante de la oreja, cruza el arco cigomático junto al nervio auriculotemporal y se divide en ramas frontal y parietal bajo la piel de la sien.', irriga: 'Cuero cabelludo de la sien y la frente, glándula parótida, parte de la cara (arteria transversa de la cara) y la oreja.', clinica: 'Su pulso se palpa delante de la oreja; en la arteritis de células gigantes (arteritis temporal) se inflama y causa dolor de cabeza, con riesgo de ceguera.', n: ['n_trigemino'] });
  add('arteria', 'a_occipital', 'Arteria occipital', 'Rama posterior de la carótida externa que irriga la nuca y la parte posterior del cuero cabelludo.', { nace: 'Cara posterior de la carótida externa, cerca del origen de la arteria facial.', recorrido: 'Va hacia atrás bajo el vientre posterior del músculo digástrico, por dentro de la apófisis mastoides, y sube por la nuca junto al nervio occipital mayor.', irriga: 'Músculos de la nuca (incluido el esternocleidomastoideo) y el cuero cabelludo de la región occipital.', clinica: 'Las heridas del cuero cabelludo sangran mucho porque el tejido denso que rodea a arterias como esta impide que se cierren al cortarse.', n: ['nervios_raquideos'] });
  add('arteria', 'a_vertebral', 'Arteria vertebral', 'Arteria que sube protegida por las vértebras del cuello y, al unirse con la del otro lado, forma la arteria basilar, que nutre la parte posterior del encéfalo.', { nace: 'Primera rama de la arteria subclavia.', recorrido: 'Sube por los agujeros transversos de las vértebras cervicales (de C6 a C1), rodea por detrás la masa lateral del atlas y entra en el cráneo por el agujero magno, donde se une a la del otro lado para formar la arteria basilar.', irriga: 'Médula espinal cervical, tronco encefálico, cerebelo y, por la basilar y las cerebrales posteriores, los lóbulos occipitales.', clinica: 'Un movimiento brusco del cuello o un traumatismo pueden desgarrar su pared (disección) y causar mareo, visión doble o un infarto en la parte posterior del encéfalo.' });
  add('arteria', 'a_cerebrales', 'Arterias cerebrales (polígono de Willis)', 'Arterias cerebrales anterior, media y posterior, unidas por las arterias comunicantes en un anillo en la base del cerebro (polígono de Willis) que permite compensar el flujo si una vía se obstruye.', { nace: 'Las anteriores y medias, de las carótidas internas; las posteriores, de la bifurcación de la arteria basilar (formada por las dos vertebrales).', recorrido: 'El polígono rodea el quiasma óptico y la hipófisis en la base del cerebro; la cerebral anterior sube entre los hemisferios, la media se mete en el surco lateral y la posterior rodea el mesencéfalo hacia el lóbulo occipital.', irriga: 'Anterior: cara interna de los lóbulos frontal y parietal. Media: casi toda la cara lateral del hemisferio, incluidas las áreas del lenguaje. Posterior: lóbulo occipital (visión) y parte inferior del temporal.', clinica: 'La arteria cerebral media es la que más se obstruye en los infartos cerebrales: causa parálisis de la cara y del brazo del lado opuesto y, si afecta al hemisferio izquierdo, trastornos del lenguaje.', v: ['senos_venosos'], n: ['n_optico'] });
  add('arteria', 'a_subclavia', 'Arteria subclavia', 'Arteria principal del miembro superior, que además da ramas al cuello, al encéfalo y a la pared del tórax.', { nace: 'La derecha, del tronco braquiocefálico; la izquierda, directamente del arco aórtico.', recorrido: 'Se arquea sobre la cúpula de la pleura y la primera costilla pasando entre los escalenos anterior y medio; en el borde externo de la primera costilla pasa a llamarse arteria axilar.', irriga: 'Por sus ramas (vertebral, torácica interna, tronco tirocervical y tronco costocervical): encéfalo, tiroides, cuello, hombro y pared del tórax; su continuación irriga todo el brazo.', clinica: 'Una costilla cervical o un escaleno anterior tenso pueden comprimirla junto con el plexo braquial (síndrome del desfiladero torácico).', v: ['v_subclavia'], n: ['plexo_braquial', 'n_frenico', 'n_vago'] });
  add('arteria', 'a_axilar', 'Arteria axilar', 'Continuación de la subclavia en la axila; el músculo pectoral menor la divide en tres porciones.', { nace: 'Continuación de la arteria subclavia en el borde externo de la primera costilla.', recorrido: 'Cruza la axila por detrás del pectoral menor, rodeada por los cordones del plexo braquial, y se convierte en arteria braquial en el borde inferior del músculo redondo mayor.', irriga: 'Por sus seis ramas (torácica superior, toracoacromial, torácica lateral, subescapular y circunflejas humerales anterior y posterior): pared del tórax, mama, hombro y músculos de la escápula.', clinica: 'Si hay que ligarla por encima del origen de la arteria subescapular, el brazo sigue recibiendo sangre por las anastomosis que rodean la escápula.', v: ['v_axilar'], n: ['plexo_braquial', 'n_mediano', 'n_cubital', 'n_radial', 'n_axilar', 'n_musculocutaneo'] });
  add('arteria', 'a_braquial', 'Arteria braquial (humeral)', 'Arteria principal del brazo, continuación de la axilar; en el codo se divide en radial y cubital.', { nace: 'Continuación de la arteria axilar en el borde inferior del músculo redondo mayor.', recorrido: 'Baja por la cara interna del brazo junto al nervio mediano, en el surco medial del bíceps; en la fosa del codo pasa bajo la aponeurosis bicipital y, frente al cuello del radio, se divide en radial y cubital.', irriga: 'Músculos anteriores del brazo, el húmero y, por la braquial profunda, los músculos posteriores; da ramas a la red arterial del codo.', clinica: 'Es la arteria que se escucha con el estetoscopio al tomar la presión arterial, en la fosa del codo, por dentro del tendón del bíceps.', v: ['v_basilica'], n: ['n_mediano', 'n_cubital'] });
  add('arteria', 'a_braquial_profunda', 'Arteria braquial profunda', 'La rama más grande de la arteria braquial; irriga la parte posterior del brazo.', { nace: 'Arteria braquial, cerca de su inicio, por debajo del músculo redondo mayor.', recorrido: 'Acompaña al nervio radial por el surco del nervio radial, rodeando el húmero por detrás entre las cabezas del tríceps, y termina en la red arterial del codo.', irriga: 'Tríceps, ancóneo, el húmero y la parte posterior y lateral del codo.', clinica: 'En una fractura de la diáfisis del húmero puede lesionarse junto con el nervio radial, que viaja con ella.', n: ['n_radial'] });
  add('arteria', 'a_radial', 'Arteria radial', 'Rama de la braquial que corre por el lado del pulgar del antebrazo; en ella se toma el pulso de la muñeca.', { nace: 'Arteria braquial, en la fosa del codo, frente al cuello del radio.', recorrido: 'Baja bajo el músculo braquiorradial, se hace superficial en la muñeca por fuera del tendón del flexor radial del carpo, cruza la tabaquera anatómica y entra en la palma entre el primero y el segundo metacarpianos.', irriga: 'Músculos del lado lateral del antebrazo, la muñeca y el pulgar; forma la mayor parte del arco palmar profundo.', clinica: 'Se usa para tomar el pulso, para extraer sangre arterial (gasometría) y como vía para los cateterismos cardíacos.', n: ['n_radial'] });
  add('arteria', 'a_cubital', 'Arteria cubital (ulnar)', 'La mayor de las dos ramas terminales de la braquial; corre por el lado del meñique del antebrazo.', { nace: 'Arteria braquial, en la fosa del codo.', recorrido: 'Pasa por debajo del pronador redondo, baja bajo el flexor cubital del carpo junto al nervio cubital y entra en la mano por fuera del hueso pisiforme (canal de Guyon), donde forma el arco palmar superficial.', irriga: 'Músculos del lado medial del antebrazo y, por la arteria interósea común, los músculos profundos y posteriores; en la mano forma la mayor parte del arco palmar superficial.', clinica: 'La prueba de Allen comprueba que la arteria cubital basta para irrigar la mano antes de puncionar o canalizar la arteria radial.', n: ['n_cubital'] });
  add('arteria', 'arcos_palmares', 'Arcos palmares y arterias digitales', 'Dos arcadas arteriales de la palma, superficial y profunda, que unen las arterias radial y cubital y reparten la sangre a los dedos.', { nace: 'El arco superficial lo forma sobre todo la arteria cubital; el profundo, sobre todo la radial.', recorrido: 'El superficial cruza la palma bajo la aponeurosis palmar, a la altura del borde del pulgar extendido; el profundo va más cerca de la muñeca, sobre las bases de los metacarpianos. De ellos salen las arterias digitales, a los lados de cada dedo.', irriga: 'Palma, músculos de la mano y dedos, por las arterias digitales palmares comunes y propias.', clinica: 'Las heridas de la palma sangran mucho porque los arcos reciben sangre por ambos extremos; comprimir una sola arteria del antebrazo no suele bastar.', n: ['n_mediano', 'n_cubital'] });
  add('arteria', 'a_toracica_interna', 'Arteria torácica interna (mamaria interna) y epigástricas', 'Arteria que baja por dentro de la pared anterior del tórax, a cada lado del esternón, y se continúa en el abdomen con las arterias epigástricas.', { nace: 'Cara inferior de la primera porción de la arteria subclavia.', recorrido: 'Baja por detrás de los cartílagos costales, cerca del borde del esternón, y en el sexto espacio intercostal se divide en musculofrénica y epigástrica superior; esta se une dentro del músculo recto del abdomen con la epigástrica inferior, rama de la ilíaca externa.', irriga: 'Pared anterior del tórax (arterias intercostales anteriores), mama, pericardio, diafragma y músculo recto del abdomen.', clinica: 'Se usa como injerto en la cirugía de revascularización coronaria (bypass) porque se mantiene abierta durante muchos años.', n: ['n_frenico', 'n_intercostales'] });
  add('arteria', 'a_intercostales', 'Arterias intercostales', 'Arterias que recorren cada espacio entre las costillas e irrigan la pared del tórax.', { nace: 'Las posteriores, de la aorta torácica (las dos primeras, del tronco costocervical de la subclavia); las anteriores, de la torácica interna y de su rama musculofrénica.', recorrido: 'Corren por el surco del borde inferior de cada costilla, entre la vena (arriba) y el nervio (abajo), y las posteriores se unen con las anteriores.', irriga: 'Músculos intercostales, costillas, piel del tórax y mama; por sus ramas dorsales, también la columna, la médula espinal y los músculos de la espalda.', clinica: 'Como van bajo el borde inferior de cada costilla, los drenajes y punciones del tórax se hacen justo por encima del borde superior de la costilla de abajo.', v: ['v_acigos'], n: ['n_intercostales'] });
  add('arteria', 'a_coronarias', 'Arterias coronarias', 'Las dos arterias que nutren el propio músculo del corazón: la coronaria derecha y la coronaria izquierda.', { nace: 'Senos aórticos derecho e izquierdo, justo por encima de la válvula aórtica.', recorrido: 'Rodean el corazón por el surco entre aurículas y ventrículos; la izquierda se divide pronto en descendente anterior y circunfleja, y la derecha baja por el borde derecho y suele dar la descendente posterior.', irriga: 'Derecha: aurícula y ventrículo derechos y, en la mayoría de las personas, los nódulos sinusal y auriculoventricular. Izquierda: aurícula y ventrículo izquierdos y la mayor parte del tabique interventricular.', clinica: 'La descendente anterior es la que más se obstruye; su oclusión produce infartos extensos de la pared anterior del ventrículo izquierdo.' });
  add('arteria', 'a_pulmonar', 'Tronco y arterias pulmonares', 'Tronco pulmonar y arterias pulmonares derecha e izquierda: llevan la sangre pobre en oxígeno del corazón a los pulmones, por eso se muestran en azul.', { nace: 'Ventrículo derecho, a través de la válvula pulmonar.', recorrido: 'El tronco pulmonar sube unos 5 cm por delante y a la izquierda de la aorta ascendente y, bajo el arco aórtico, se divide en las arterias pulmonares derecha e izquierda, que entran en cada pulmón por su hilio.', irriga: 'No nutre los pulmones: lleva la sangre a los capilares de los alvéolos para que se oxigene.', clinica: 'Un coágulo que viaja desde las venas de las piernas puede tapar estas arterias (embolia pulmonar) y causar falta de aire súbita, dolor en el pecho e incluso la muerte.', v: ['v_pulmonares'] });
  add('arteria', 'tronco_celiaco', 'Tronco celíaco', 'Rama corta de la aorta abdominal que irriga los órganos de la parte alta del abdomen.', { nace: 'Cara anterior de la aorta abdominal, justo por debajo del hiato aórtico, a la altura de T12.', recorrido: 'Tras un trayecto muy corto, por encima del páncreas, se divide en tres ramas: gástrica izquierda, esplénica y hepática común.', irriga: 'Esófago abdominal, estómago, primera mitad del duodeno, hígado, vesícula, páncreas y bazo.', clinica: 'Sus ramas se comunican con las de la mesentérica superior alrededor del páncreas, lo que permite compensar la obstrucción lenta de cualquiera de las dos.', v: ['v_porta'], n: ['tronco_simpatico', 'n_vago'] });
  add('arteria', 'a_hepatica', 'Arteria hepática', 'Arteria que lleva sangre rica en oxígeno al hígado y a la vesícula; aporta cerca de la cuarta parte de la sangre que recibe el hígado.', { nace: 'La hepática común sale del tronco celíaco; después de dar la arteria gastroduodenal se llama hepática propia.', recorrido: 'Va hacia la derecha por encima del páncreas y sube por el ligamento hepatoduodenal, a la izquierda del colédoco y por delante de la vena porta, hasta dividirse en ramas derecha e izquierda en el hilio del hígado.', irriga: 'Hígado y vesícula (por la arteria cística); sus ramas gástrica derecha y gastroduodenal irrigan también estómago, duodeno y páncreas.', clinica: 'Su rama derecha suele dar la arteria cística, que el cirujano identifica y liga al extirpar la vesícula.', v: ['v_porta'], n: ['n_vago', 'tronco_simpatico'] });
  add('arteria', 'a_esplenica', 'Arteria esplénica', 'La rama más grande del tronco celíaco; lleva sangre al bazo y a parte del estómago y del páncreas.', { nace: 'Tronco celíaco.', recorrido: 'Corre hacia la izquierda, muy sinuosa, por el borde superior del páncreas y por detrás del estómago, hasta el hilio del bazo.', irriga: 'Bazo, cuerpo y cola del páncreas y, por las gástricas cortas y la gastroomental izquierda, el fondo y la curvatura mayor del estómago.', clinica: 'Es la arteria de las vísceras abdominales donde más se forman aneurismas; su rotura causa una hemorragia grave.', v: ['v_porta'] });
  add('arteria', 'a_mesenterica_superior', 'Arteria mesentérica superior', 'Gran rama de la aorta que irriga el intestino desde la mitad del duodeno hasta los dos tercios del colon transverso.', { nace: 'Cara anterior de la aorta abdominal, a la altura de L1, poco por debajo del tronco celíaco.', recorrido: 'Baja por detrás del cuello del páncreas, cruza por delante de la vena renal izquierda y de la tercera porción del duodeno y entra en la raíz del mesenterio, donde da sus ramas en abanico.', irriga: 'Parte del páncreas y del duodeno, todo el yeyuno y el íleon, el ciego, el apéndice, el colon ascendente y la mayor parte del transverso.', clinica: 'Su obstrucción brusca, por ejemplo por un coágulo que viene del corazón, causa isquemia intestinal aguda: un dolor abdominal muy intenso con un abdomen que al principio parece normal.', v: ['v_porta'], n: ['tronco_simpatico', 'n_vago'] });
  add('arteria', 'a_mesenterica_inferior', 'Arteria mesentérica inferior', 'La más pequeña de las tres ramas digestivas de la aorta; irriga la parte final del intestino grueso.', { nace: 'Cara anterior de la aorta abdominal, a la altura de L3.', recorrido: 'Desciende por detrás del peritoneo hacia la izquierda y, al cruzar los vasos ilíacos comunes izquierdos, continúa como arteria rectal superior.', irriga: 'Tercio izquierdo del colon transverso, colon descendente, sigmoide y parte superior del recto (arterias cólica izquierda, sigmoideas y rectal superior).', clinica: 'Se une a la mesentérica superior por la arteria marginal del colon; la zona de unión, cerca del ángulo esplénico, es la más sensible a la falta de riego.', v: ['v_porta'], n: ['tronco_simpatico'] });
  add('arteria', 'a_renal', 'Arterias renales', 'Dos arterias cortas y gruesas que llevan a los riñones una gran cantidad de sangre para ser filtrada.', { nace: 'Caras laterales de la aorta abdominal, a la altura del disco entre L1 y L2.', recorrido: 'Van hacia los lados hasta el hilio de cada riñón; la derecha, más larga, pasa por detrás de la vena cava inferior.', irriga: 'Riñones, y además ramas para las glándulas suprarrenales y la parte alta de los uréteres.', clinica: 'Su estrechamiento (estenosis de la arteria renal) activa el sistema renina-angiotensina y causa hipertensión arterial secundaria.', v: ['v_renal'], n: ['tronco_simpatico'] });
  add('arteria', 'a_iliaca_comun', 'Arteria ilíaca común', 'Cada una de las dos ramas terminales de la aorta abdominal; lleva la sangre a la pelvis y a las piernas.', { nace: 'Bifurcación de la aorta abdominal, a la altura de L4.', recorrido: 'Baja hacia afuera siguiendo el borde del músculo psoas y, delante de la articulación sacroilíaca, se divide en ilíaca interna y externa; el uréter la cruza por delante en esa zona.', irriga: 'Por sus ramas interna y externa, la pelvis, sus órganos, los glúteos y todo el miembro inferior.', clinica: 'Su obstrucción por aterosclerosis causa dolor en glúteos y muslos al caminar que se alivia al descansar (claudicación intermitente).', v: ['v_iliaca_comun'] });
  add('arteria', 'a_iliaca_interna', 'Arteria ilíaca interna (y arterias glúteas)', 'Arteria principal de la pelvis; irriga los órganos pélvicos, el periné, los glúteos y la parte medial del muslo.', { nace: 'Bifurcación de la arteria ilíaca común, delante de la articulación sacroilíaca.', recorrido: 'Baja hacia la pelvis y se divide en un tronco anterior (ramas viscerales, obturatriz, pudenda interna y glútea inferior) y uno posterior (iliolumbar, sacras laterales y glútea superior); las glúteas salen por el agujero ciático mayor.', irriga: 'Vejiga, recto, útero y vagina o próstata, periné y genitales, músculos glúteos (por las glúteas superior e inferior) y aductores del muslo (por la obturatriz).', clinica: 'En las hemorragias graves por fractura de pelvis o tras el parto se pueden embolizar sus ramas para detener el sangrado.', v: ['v_iliaca_interna'], n: ['plexo_sacro', 'n_gluteo_superior', 'n_gluteo_inferior', 'n_obturador'] });
  add('arteria', 'a_iliaca_externa', 'Arteria ilíaca externa', 'Rama de la ilíaca común que lleva la sangre al miembro inferior; al pasar bajo el ligamento inguinal se convierte en arteria femoral.', { nace: 'Bifurcación de la arteria ilíaca común, delante de la articulación sacroilíaca.', recorrido: 'Sigue el borde medial del músculo psoas por la pelvis y pasa bajo el ligamento inguinal a medio camino entre la espina ilíaca anterosuperior y la sínfisis del pubis.', irriga: 'Todo el miembro inferior a través de la femoral; además da la epigástrica inferior (pared del abdomen) y la circunfleja ilíaca profunda.', clinica: 'Su rama epigástrica inferior sirve para distinguir la hernia inguinal directa (sale por dentro de ella) de la indirecta (por fuera).', v: ['v_iliaca_externa'], n: ['n_femoral'] });
  add('arteria', 'a_femoral', 'Arteria femoral', 'Arteria principal del muslo, continuación de la ilíaca externa; da la femoral profunda y continúa hasta detrás de la rodilla.', { nace: 'Continuación de la arteria ilíaca externa al pasar bajo el ligamento inguinal.', recorrido: 'Cruza el triángulo femoral entre el nervio femoral (por fuera) y la vena femoral (por dentro); luego baja por el conducto aductor bajo el sartorio y pasa por el hiato del aductor mayor a la parte posterior de la rodilla, donde se llama arteria poplítea.', irriga: 'Piel de la ingle y de la parte baja del abdomen, genitales externos y músculos del muslo; su rama femoral profunda irriga la mayor parte del muslo.', clinica: 'Su pulso se palpa en la ingle, en el punto medio entre la espina ilíaca anterosuperior y la sínfisis del pubis; es una vía muy usada para los cateterismos.', v: ['v_femoral'], n: ['n_femoral', 'n_safeno'] });
  add('arteria', 'a_femoral_profunda', 'Arteria femoral profunda', 'La rama más grande de la arteria femoral y la principal arteria del muslo.', { nace: 'Cara lateral o posterior de la arteria femoral, unos centímetros por debajo del ligamento inguinal.', recorrido: 'Baja por detrás de la femoral, entre los músculos aductores, y da las arterias circunflejas femorales medial y lateral y tres o cuatro arterias perforantes que rodean el fémur por detrás.', irriga: 'Cabeza y cuello del fémur (por las circunflejas), cuádriceps, aductores e isquiotibiales (por las perforantes).', clinica: 'La circunfleja femoral medial lleva casi toda la sangre a la cabeza del fémur; si se rompe en una fractura del cuello femoral, la cabeza puede necrosarse.', v: ['v_femoral'] });
  add('arteria', 'a_poplitea', 'Arteria poplítea', 'Continuación de la arteria femoral detrás de la rodilla; es la estructura más profunda de la fosa poplítea.', { nace: 'Continuación de la femoral al pasar por el hiato del aductor mayor.', recorrido: 'Cruza la fosa poplítea pegada a la cápsula de la rodilla, más profunda que la vena poplítea y el nervio tibial, y en el borde inferior del músculo poplíteo se divide en tibiales anterior y posterior.', irriga: 'Articulación de la rodilla (arterias geniculares) y músculos de la pantorrilla, como los gemelos (arterias surales).', clinica: 'En una luxación de rodilla puede desgarrarse porque está muy fija al hueso; por eso siempre se revisan los pulsos del pie.', v: ['v_poplitea'], n: ['n_tibial', 'n_peroneo_comun'] });
  add('arteria', 'a_tibial_anterior', 'Arteria tibial anterior', 'Rama de la poplítea que irriga la parte anterior de la pierna y continúa en el pie como arteria dorsal.', { nace: 'Arteria poplítea, en el borde inferior del músculo poplíteo.', recorrido: 'Pasa hacia adelante por encima de la membrana interósea y baja sobre ella junto al nervio peroneo profundo; al cruzar el tobillo, entre los maléolos, se convierte en arteria dorsal del pie.', irriga: 'Músculos del compartimento anterior de la pierna (tibial anterior y extensores) y las redes arteriales de la rodilla y del tobillo.', clinica: 'En el síndrome compartimental anterior, la hinchazón dentro de la fascia comprime sus vasos y nervios y puede dañar los músculos que levantan el pie.', v: ['v_poplitea'], n: ['n_peroneo_profundo'] });
  add('arteria', 'a_tibial_posterior', 'Arteria tibial posterior', 'La rama más grande de la poplítea; irriga la parte posterior de la pierna y la planta del pie.', { nace: 'Arteria poplítea, en el borde inferior del músculo poplíteo.', recorrido: 'Baja entre los músculos profundos de la pantorrilla junto al nervio tibial, pasa por detrás del maléolo medial, bajo el retináculo flexor, y bajo el abductor del dedo gordo se divide en arterias plantares medial y lateral.', irriga: 'Músculos posteriores de la pierna, la tibia y, por las plantares, la planta del pie; da además la arteria peronea.', clinica: 'Su pulso se palpa entre el maléolo medial y el tendón de Aquiles; se revisa en personas con diabetes o con enfermedad arterial de las piernas.', v: ['v_poplitea'], n: ['n_tibial'] });
  add('arteria', 'a_peronea', 'Arteria peronea (fibular)', 'La rama más grande de la tibial posterior; irriga el lado externo de la pantorrilla.', { nace: 'Arteria tibial posterior, poco por debajo del músculo poplíteo.', recorrido: 'Baja junto al peroné, entre el flexor largo del dedo gordo y el tibial posterior, y termina en ramas alrededor del maléolo lateral y del talón.', irriga: 'Músculos posteriores y laterales (peroneos) de la pierna, el peroné y la red arterial del tobillo.', clinica: 'Con ella y el peroné se prepara el colgajo libre de peroné, que se usa para reconstruir la mandíbula después de extirpar un tumor.', v: ['v_poplitea'] });
  add('arteria', 'a_dorsal_pie', 'Arteria dorsal del pie (pedia)', 'Continuación de la arteria tibial anterior en el dorso del pie.', { nace: 'Continuación de la tibial anterior a mitad de camino entre los dos maléolos.', recorrido: 'Corre sobre los huesos del tarso, por fuera del tendón del extensor largo del dedo gordo, hasta el primer espacio entre los metatarsianos, donde se hunde hacia la planta y se une al arco plantar profundo.', irriga: 'Dorso del pie y de los dedos (por la arteria arqueada y las metatarsianas dorsales) y, a través del arco plantar, parte de la planta.', clinica: 'Su pulso (pulso pedio) se palpa en el dorso del pie, por fuera del tendón del dedo gordo; si falta, puede indicar enfermedad arterial.', n: ['n_peroneo_profundo'] });
  add('arteria', 'a_plantares', 'Arterias plantares', 'Ramas terminales de la tibial posterior que irrigan la planta del pie: arterias plantares medial y lateral.', { nace: 'Arteria tibial posterior, bajo el músculo abductor del dedo gordo.', recorrido: 'La medial va por el borde interno de la planta; la lateral, más grande, cruza hacia afuera y luego vuelve hacia adentro formando el arco plantar profundo, que se une con la arteria dorsal del pie.', irriga: 'Músculos, piel y articulaciones de la planta y de los dedos, por las arterias metatarsianas y digitales plantares.', clinica: 'Las heridas profundas de la planta que cortan el arco plantar sangran mucho, por ambos extremos de la arteria, debido a sus abundantes anastomosis.', n: ['n_plantares'] });

  // ============================ VENAS ============================
  add('vena', 'v_cava_superior', 'Vena cava superior', 'Gran vena sin válvulas que devuelve al corazón la sangre de la mitad superior del cuerpo.', { drena: 'Cabeza, cuello, miembros superiores y, a través de la vena ácigos, la pared del tórax.', recorrido: 'Se forma detrás del primer cartílago costal derecho por la unión de las dos venas braquiocefálicas y baja a la derecha de la aorta ascendente; antes de llegar al corazón recibe la vena ácigos.', desemboca: 'Aurícula derecha, a la altura del tercer cartílago costal derecho.', clinica: 'Un tumor del pulmón o del mediastino puede comprimirla (síndrome de vena cava superior): se hinchan la cara, el cuello y los brazos y se marcan las venas del pecho.', a: ['aorta'] });
  add('vena', 'v_cava_inferior', 'Vena cava inferior', 'La vena más grande del cuerpo; devuelve al corazón la sangre de la mitad inferior del cuerpo.', { drena: 'Miembros inferiores, pelvis, riñones, suprarrenales, pared del abdomen y, por las venas hepáticas, la sangre del hígado y del tubo digestivo.', recorrido: 'Se forma a la altura de L5 por la unión de las dos ilíacas comunes, sube a la derecha de la aorta, pasa por detrás del hígado y atraviesa el diafragma a la altura de T8.', desemboca: 'Aurícula derecha.', clinica: 'Al final del embarazo, acostarse boca arriba hace que el útero la comprima y puede bajar la presión de la madre; por eso se recomienda acostarse sobre el lado izquierdo.', a: ['aorta_abdominal'] });
  add('vena', 'v_braquiocefalica', 'Venas braquiocefálicas', 'Dos troncos venosos, derecho e izquierdo, que se unen para formar la vena cava superior; el izquierdo es más del doble de largo que el derecho.', { drena: 'Cabeza, cuello y miembros superiores; reciben además las venas vertebrales, torácicas internas y tiroideas inferiores.', recorrido: 'Cada una se forma detrás de la articulación esternoclavicular por la unión de la yugular interna y la subclavia; la izquierda cruza hacia la derecha por delante de las ramas del arco aórtico.', desemboca: 'Vena cava superior, detrás del primer cartílago costal derecho.', clinica: 'En la unión de la yugular interna y la subclavia izquierdas (ángulo venoso) desemboca el conducto torácico, que devuelve la linfa a la sangre.', a: ['tronco_braquiocefalico'] });
  add('vena', 'v_yugular_interna', 'Vena yugular interna', 'La vena principal del cuello; recoge la sangre del encéfalo, de la cara y del cuello.', { drena: 'Encéfalo y cráneo (a través de los senos venosos) y cara y cuello (por las venas facial, lingual y tiroideas).', recorrido: 'Comienza en el agujero yugular como continuación del seno sigmoideo y baja por el cuello dentro de la vaina carotídea, por fuera de la carótida y junto al nervio vago, cubierta por el esternocleidomastoideo.', desemboca: 'Se une a la subclavia detrás del extremo medial de la clavícula para formar la vena braquiocefálica.', clinica: 'Es una vía habitual para colocar catéteres venosos centrales, hoy guiados por ecografía.', a: ['a_carotida_comun', 'a_carotida_interna'] });
  add('vena', 'v_yugular_externa', 'Vena yugular externa', 'Vena superficial del cuello, visible bajo la piel sobre el músculo esternocleidomastoideo.', { drena: 'Cuero cabelludo y partes laterales de la cara y del cuello.', recorrido: 'Se forma detrás del ángulo de la mandíbula por la unión de la vena retromandibular (rama posterior) y la auricular posterior, y baja cruzando en diagonal el esternocleidomastoideo, bajo el músculo platisma.', desemboca: 'Vena subclavia, por encima de la parte media de la clavícula.', clinica: 'Se hincha y se marca al toser, al hacer fuerza o cuando la presión venosa está elevada, como en la insuficiencia cardíaca.' });
  add('vena', 'v_facial', 'Vena facial', 'La vena principal de la cara; acompaña a la arteria facial.', { drena: 'Frente, párpados, nariz, labios, mejillas y la región situada bajo la mandíbula.', recorrido: 'Comienza en el ángulo interno del ojo como vena angular, baja por detrás de la arteria facial y cruza el borde de la mandíbula por delante del masetero.', desemboca: 'Vena yugular interna, cerca del hueso hioides.', clinica: 'Se comunica con el seno cavernoso por las venas oftálmicas; por eso las infecciones del "triángulo peligroso" de la cara (nariz y labio superior) pueden llegar al cerebro.', a: ['a_facial'] });
  add('vena', 'senos_venosos', 'Senos venosos de la duramadre', 'Canales venosos sin válvulas, entre las dos capas de la duramadre, que recogen la sangre del encéfalo; los principales son el sagital superior, el recto, los transversos, los sigmoideos y los cavernosos.', { drena: 'Encéfalo, meninges, huesos del cráneo y, por las venas oftálmicas, la órbita; además reabsorben el líquido cefalorraquídeo.', recorrido: 'El sagital superior corre hacia atrás por la línea media del cráneo; en la confluencia de los senos, junto a la protuberancia occipital interna, la sangre pasa a los senos transversos y de ahí a los sigmoideos, que bajan hasta el agujero yugular.', desemboca: 'Venas yugulares internas, en los agujeros yugulares.', clinica: 'La trombosis de un seno venoso puede causar un dolor de cabeza intenso, convulsiones y aumento de la presión dentro del cráneo.', a: ['a_carotida_interna'] });
  add('vena', 'v_subclavia', 'Vena subclavia', 'Continuación de la vena axilar; lleva la sangre del miembro superior hacia el corazón.', { drena: 'Miembro superior (a través de la axilar) y, por la yugular externa, parte de la cabeza y del cuello.', recorrido: 'Comienza en el borde externo de la primera costilla y pasa por detrás de la clavícula y por delante del músculo escaleno anterior, que la separa de la arteria subclavia.', desemboca: 'Se une con la yugular interna detrás de la articulación esternoclavicular para formar la vena braquiocefálica.', clinica: 'Se usa para colocar catéteres venosos centrales por debajo de la clavícula; un riesgo de esta punción es perforar la pleura y causar un neumotórax.', a: ['a_subclavia'] });
  add('vena', 'v_axilar', 'Vena axilar', 'Gran vena de la axila que recoge toda la sangre del miembro superior.', { drena: 'Brazo, antebrazo y mano (por las venas basílica, braquiales y cefálica), además de parte de la pared del tórax y de la mama.', recorrido: 'Se forma en el borde inferior del redondo mayor por la unión de la vena basílica con las venas braquiales y sube por la axila por dentro de la arteria axilar.', desemboca: 'Se convierte en vena subclavia en el borde externo de la primera costilla.', clinica: 'El esfuerzo repetido con los brazos en alto puede trombosarla (síndrome de Paget-Schroetter): el brazo se hincha y toma un color violáceo.', a: ['a_axilar'] });
  add('vena', 'v_cefalica', 'Vena cefálica', 'Vena superficial del lado del pulgar del miembro superior.', { drena: 'Lado lateral (radial) de la mano, del antebrazo y del brazo.', recorrido: 'Nace en la red venosa dorsal de la mano, sube por el borde radial del antebrazo y por fuera del bíceps y pasa por el surco entre el deltoides y el pectoral mayor (surco deltopectoral).', desemboca: 'Vena axilar, tras atravesar la fascia clavipectoral bajo la clavícula.', clinica: 'En el surco deltopectoral se usa como vía de acceso para implantar los cables de los marcapasos.' });
  add('vena', 'v_basilica', 'Vena basílica', 'Vena superficial del lado del meñique del miembro superior.', { drena: 'Lado medial (cubital) de la mano, del antebrazo y del brazo.', recorrido: 'Nace en la red venosa dorsal de la mano, sube por el borde cubital del antebrazo y, hacia la mitad del brazo, atraviesa la fascia profunda y continúa junto a la arteria braquial.', desemboca: 'Se une con las venas braquiales en el borde inferior del redondo mayor para formar la vena axilar.', clinica: 'Por su trayecto recto y su buen calibre es la vena preferida para colocar catéteres centrales de inserción periférica (PICC).', a: ['a_braquial'] });
  add('vena', 'v_mediana_cubital', 'Vena mediana cubital', 'Vena superficial que cruza en diagonal la parte anterior del codo y une la vena cefálica con la basílica.', { drena: 'Comunica la cefálica con la basílica y recibe venas del antebrazo y una vena profunda que la fija en su sitio.', recorrido: 'Va desde la cefálica, abajo y por fuera, hasta la basílica, arriba y por dentro, sobre la aponeurosis bicipital, que la separa de la arteria braquial y del nervio mediano.', desemboca: 'Vena basílica.', clinica: 'Es la vena más usada para sacar sangre porque es superficial, gruesa y está bien fija.', a: ['a_braquial'] });
  add('vena', 'red_venosa_mano', 'Red venosa dorsal de la mano', 'Red de venas superficiales que se ve en el dorso de la mano.', { drena: 'Dedos (por las venas metacarpianas dorsales) y la mayor parte de la sangre superficial de la mano, incluida la que viene de la palma.', recorrido: 'Se forma sobre los metacarpianos; su extremo del lado del pulgar origina la vena cefálica y el del lado del meñique, la basílica.', desemboca: 'Venas cefálica y basílica.', clinica: 'Es un sitio habitual para colocar cánulas intravenosas porque sus venas son visibles y fáciles de alcanzar.' });
  add('vena', 'v_acigos', 'Sistema ácigos y venas intercostales', 'Sistema de venas a los lados de la columna torácica (ácigos a la derecha, hemiácigos y hemiácigos accesoria a la izquierda) que recoge la sangre de la pared del tórax.', { drena: 'Venas intercostales posteriores, bronquiales, esofágicas y de la pared posterior del abdomen.', recorrido: 'La ácigos sube a la derecha de los cuerpos vertebrales, junto a la aorta y el conducto torácico, y a la altura de T4 se arquea sobre el bronquio principal derecho; las hemiácigos cruzan la línea media para unirse a ella.', desemboca: 'Vena cava superior.', clinica: 'Si se obstruye la vena cava inferior, el sistema ácigos sirve de camino alternativo para que la sangre vuelva al corazón.', a: ['a_intercostales', 'aorta'] });
  add('vena', 'v_pulmonares', 'Venas pulmonares', 'Cuatro venas, dos de cada pulmón, que llevan la sangre ya oxigenada de los pulmones al corazón; por eso se muestran en rojo.', { drena: 'Capilares de los alvéolos pulmonares, donde la sangre recibió oxígeno.', recorrido: 'Salen por el hilio de cada pulmón, una superior y una inferior por lado, y van hacia la cara posterior del corazón.', desemboca: 'Aurícula izquierda.', clinica: 'La fibrilación auricular suele iniciarse en el músculo que rodea su desembocadura; por eso se trata aislándolas eléctricamente mediante ablación.', a: ['a_pulmonar'] });
  add('vena', 'v_porta', 'Vena porta (con esplénica y mesentéricas)', 'Vena que lleva al hígado la sangre del tubo digestivo, del bazo y del páncreas, rica en nutrientes, para que la procese antes de que pase al resto del cuerpo.', { drena: 'Estómago, intestinos (hasta la parte alta del recto), bazo, páncreas y vesícula, a través de las venas esplénica y mesentéricas superior e inferior.', recorrido: 'Se forma detrás del cuello del páncreas por la unión de la mesentérica superior y la esplénica (que suele recibir a la mesentérica inferior) y sube por el ligamento hepatoduodenal, por detrás del colédoco y de la arteria hepática.', desemboca: 'Hígado: en su hilio se divide en ramas derecha e izquierda que terminan en los sinusoides hepáticos.', clinica: 'En la cirrosis aumenta su presión (hipertensión portal) y la sangre busca caminos alternativos: várices del esófago, hemorroides y venas dilatadas alrededor del ombligo.', a: ['tronco_celiaco', 'a_hepatica', 'a_esplenica', 'a_mesenterica_superior', 'a_mesenterica_inferior'] });
  add('vena', 'v_hepaticas', 'Venas hepáticas', 'Tres venas cortas, derecha, media e izquierda, que sacan del hígado toda la sangre que entró por la vena porta y la arteria hepática.', { drena: 'Todo el hígado, a partir de las venas centrales de sus lobulillos.', recorrido: 'Corren dentro del hígado entre sus segmentos, sin acompañar a las ramas de la porta, y salen por su cara posterior.', desemboca: 'Vena cava inferior, justo debajo del diafragma.', clinica: 'Su obstrucción por trombosis (síndrome de Budd-Chiari) agranda el hígado y acumula líquido en el abdomen (ascitis).' });
  add('vena', 'v_renal', 'Venas renales', 'Venas cortas y gruesas que devuelven la sangre filtrada de cada riñón; la izquierda es mucho más larga que la derecha.', { drena: 'Riñones; la izquierda recibe además las venas suprarrenal y gonadal (testicular u ovárica) de su lado.', recorrido: 'Van del hilio renal a la vena cava; la izquierda cruza por delante de la aorta, justo por debajo del origen de la arteria mesentérica superior.', desemboca: 'Vena cava inferior.', clinica: 'La vena renal izquierda puede quedar comprimida entre la aorta y la mesentérica superior (síndrome del cascanueces), con sangre en la orina o várices en el testículo izquierdo.', a: ['a_renal'] });
  add('vena', 'v_iliaca_comun', 'Venas ilíacas comunes', 'Dos troncos venosos que recogen la sangre de la pelvis y de las piernas y se unen para formar la vena cava inferior.', { drena: 'Miembros inferiores (por la ilíaca externa) y pelvis (por la ilíaca interna).', recorrido: 'Cada una se forma delante de la articulación sacroilíaca y sube hacia la línea media; la izquierda, más larga, pasa por detrás de la arteria ilíaca común derecha.', desemboca: 'Se unen a la altura de L5, a la derecha de la línea media, para formar la vena cava inferior.', clinica: 'La compresión de la ilíaca común izquierda por la arteria ilíaca común derecha (síndrome de May-Thurner) favorece la trombosis de la pierna izquierda.', a: ['a_iliaca_comun'] });
  add('vena', 'v_iliaca_interna', 'Vena ilíaca interna', 'Vena principal de la pelvis; acompaña a la arteria ilíaca interna.', { drena: 'Órganos de la pelvis (vejiga, recto, útero o próstata), glúteos, periné y parte de los genitales externos.', recorrido: 'Se forma por la unión de las venas glúteas, pudendas internas, obturatrices y de los plexos venosos de la pelvis, y sube por detrás de la arteria ilíaca interna.', desemboca: 'Se une a la ilíaca externa delante de la articulación sacroilíaca para formar la vena ilíaca común.', clinica: 'Sus plexos se comunican con los plexos venosos de la columna; por esa vía el cáncer de próstata puede extenderse a las vértebras.', a: ['a_iliaca_interna'] });
  add('vena', 'v_iliaca_externa', 'Vena ilíaca externa', 'Continuación de la vena femoral dentro de la pelvis.', { drena: 'Todo el miembro inferior y, por la vena epigástrica inferior, parte de la pared del abdomen.', recorrido: 'Comienza detrás del ligamento inguinal y sube por el borde de la pelvis, por dentro de la arteria ilíaca externa.', desemboca: 'Se une a la ilíaca interna para formar la vena ilíaca común.', clinica: 'Las trombosis venosas profundas que llegan hasta las venas ilíacas tienen un riesgo alto de producir embolia pulmonar.', a: ['a_iliaca_externa'] });
  add('vena', 'v_femoral', 'Vena femoral', 'Vena profunda principal del muslo; acompaña a la arteria femoral.', { drena: 'Muslo y pierna (por la poplítea y la femoral profunda) y la sangre superficial que le llega por la safena mayor.', recorrido: 'Sube desde el hiato del aductor mayor por el conducto aductor, detrás de la arteria, y en el triángulo femoral se coloca por dentro de ella.', desemboca: 'Se convierte en vena ilíaca externa al pasar por detrás del ligamento inguinal.', clinica: 'En la ingle está justo por dentro del pulso femoral, lo que permite puncionarla para colocar catéteres venosos.', a: ['a_femoral', 'a_femoral_profunda'] });
  add('vena', 'v_poplitea', 'Vena poplítea y venas tibiales', 'Venas profundas de la pierna: las tibiales anteriores, tibiales posteriores y peroneas, que van en parejas junto a sus arterias, se unen detrás de la rodilla para formar la vena poplítea.', { drena: 'Músculos y huesos de la pierna y del pie; la poplítea recibe además la vena safena menor.', recorrido: 'La poplítea sube por la fosa poplítea entre la arteria, más profunda, y el nervio tibial, más superficial.', desemboca: 'Se convierte en vena femoral al pasar por el hiato del aductor mayor.', clinica: 'La trombosis venosa profunda suele comenzar en las venas de la pantorrilla; es más frecuente después de cirugías, viajes largos o períodos de inmovilización.', a: ['a_poplitea', 'a_tibial_anterior', 'a_tibial_posterior', 'a_peronea'] });
  add('vena', 'v_safena_mayor', 'Vena safena mayor (interna)', 'La vena más larga del cuerpo; sube por debajo de la piel del lado interno de la pierna y del muslo.', { drena: 'Piel y tejido subcutáneo del pie, de la cara medial de la pierna y de casi todo el muslo.', recorrido: 'Nace en el extremo medial del arco venoso dorsal del pie, pasa por delante del maléolo medial, sube por la cara medial de la pierna y por detrás del cóndilo medial del fémur hasta la ingle.', desemboca: 'Vena femoral, a través del hiato safeno, por debajo y por fuera del tubérculo del pubis.', clinica: 'Se extrae con frecuencia para usarla como injerto en la cirugía de revascularización coronaria (bypass).' });
  add('vena', 'v_safena_menor', 'Vena safena menor (externa)', 'Vena superficial de la parte posterior de la pierna.', { drena: 'Borde lateral del pie y piel de la pantorrilla.', recorrido: 'Nace en el extremo lateral del arco venoso dorsal del pie, pasa por detrás del maléolo lateral junto al nervio sural y sube por el centro de la pantorrilla, entre las dos cabezas del gastrocnemio.', desemboca: 'Vena poplítea, en la fosa poplítea.', clinica: 'Cuando sus válvulas no cierran bien, la sangre se estanca y aparecen várices en la parte posterior de la pantorrilla.' });
  add('vena', 'arco_venoso_pie', 'Arco venoso dorsal del pie', 'Arco de venas superficiales que cruza el dorso del pie sobre los metatarsianos.', { drena: 'Dedos (por las venas digitales y metatarsianas dorsales) y gran parte de la piel del pie.', recorrido: 'Cruza el dorso del pie de un lado a otro; su extremo medial forma la vena safena mayor y su extremo lateral, la safena menor.', desemboca: 'Venas safena mayor y safena menor.', clinica: 'Sus venas se usan para colocar una vía intravenosa cuando no hay acceso en los brazos, sobre todo en bebés.' });

  // ============================ NERVIOS ============================
  add('nervio', 'nervios_raquideos', 'Nervios raquídeos (31 pares)', 'Los 31 pares de nervios que salen de la médula espinal: 8 cervicales, 12 torácicos, 5 lumbares, 5 sacros y 1 coccígeo. Son mixtos: llevan órdenes a los músculos y traen la sensibilidad de la piel.', { raices: 'Cada nervio nace de un segmento de la médula por la unión de una raíz anterior (motora) y una posterior (sensitiva, con su ganglio).', recorrido: 'Salen por los agujeros intervertebrales y enseguida se dividen en un ramo posterior, para la espalda, y uno anterior, que forma los plexos cervical, braquial, lumbar y sacro o, en el tórax, los nervios intercostales.', inerva: 'Los ramos posteriores, los músculos profundos de la espalda (como el erector de la columna); los anteriores, los músculos del cuello, del tronco y de las extremidades.', piel: 'Cada nervio recoge la sensibilidad de una franja de piel llamada dermatoma; por ejemplo, T10 corresponde a la altura del ombligo.', clinica: 'El herpes zóster (culebrilla) reactiva el virus de la varicela en el ganglio de una raíz posterior y causa una erupción dolorosa limitada a un dermatoma.', a: ['a_intercostales'] });
  add('nervio', 'tronco_simpatico', 'Tronco simpático', 'Cadena de ganglios nerviosos a cada lado de la columna, desde la base del cráneo hasta el cóccix; es la parte principal del sistema nervioso simpático, que prepara al cuerpo para la acción ("lucha o huida").', { raices: 'Recibe fibras de las astas laterales de la médula entre T1 y L2 (ramos comunicantes blancos).', recorrido: 'Baja por delante de las apófisis transversas en el cuello, sobre las cabezas de las costillas en el tórax y a los lados de los cuerpos vertebrales en el abdomen; en el cuello tiene tres ganglios (superior, medio e inferior) y los dos troncos se unen frente al cóccix en el ganglio impar.', inerva: 'Músculo liso de los vasos y de las vísceras, glándulas sudoríparas, músculos erectores del pelo, corazón y músculo dilatador de la pupila; por los nervios esplácnicos llega a las vísceras del abdomen.', clinica: 'Su lesión en el cuello produce el síndrome de Horner: párpado caído, pupila pequeña y falta de sudor en ese lado de la cara.' });
  add('nervio', 'n_optico', 'Nervio óptico (II par craneal)', 'Nervio de la visión, que lleva al cerebro las señales que forma la retina. En realidad es una prolongación del encéfalo, envuelta por las meninges.', { raices: 'Células ganglionares de la retina; se desarrolla como una prolongación del diencéfalo.', recorrido: 'Sale por la parte posterior del ojo, cruza la órbita, entra en el cráneo por el conducto óptico y se une al del otro lado en el quiasma óptico, donde se cruzan las fibras de la mitad nasal de cada retina.', inerva: 'Ningún músculo: es un nervio exclusivamente sensorial, de la vista.', clinica: 'Un tumor de la hipófisis puede comprimir el quiasma óptico y hacer perder la visión de las dos mitades externas del campo visual (hemianopsia bitemporal).', a: ['a_carotida_interna'] });
  add('nervio', 'n_trigemino', 'Nervio trigémino (V par craneal)', 'El mayor de los nervios craneales: da la sensibilidad de la cara y mueve los músculos de la masticación. Tiene tres ramas: oftálmica (V1), maxilar (V2) y mandibular (V3).', { raices: 'Puente (protuberancia) del tronco encefálico; su ganglio sensitivo, el ganglio trigeminal, está en la fosa media del cráneo.', recorrido: 'V1 entra en la órbita por la fisura orbitaria superior, V2 sale del cráneo por el agujero redondo y V3 por el agujero oval; sus ramas llegan a la piel por agujeros como el supraorbitario, el infraorbitario y el mentoniano.', inerva: 'Músculos de la masticación (masetero, temporal y pterigoideos) y otros pequeños como el milohioideo y el vientre anterior del digástrico, todos por V3.', piel: 'Casi toda la cara y la parte anterior del cuero cabelludo, además de la córnea, la boca, los dientes y las fosas nasales.', clinica: 'La neuralgia del trigémino causa crisis de dolor muy intenso, como descargas eléctricas, en una zona de la cara, a menudo al masticar o al tocarla.', a: ['a_temporal_superficial'] });
  add('nervio', 'n_facial', 'Nervio facial (VII par craneal)', 'Nervio que mueve los músculos de la expresión facial; también lleva el gusto de la parte anterior de la lengua y estimula las glándulas lagrimales y algunas salivales.', { raices: 'Tronco encefálico, en el límite entre el puente y el bulbo raquídeo.', recorrido: 'Entra en el hueso temporal por el conducto auditivo interno, recorre el conducto facial, sale por el agujero estilomastoideo y dentro de la parótida se divide en cinco ramas: temporal, cigomática, bucal, mandibular y cervical.', inerva: 'Músculos de la mímica (frontal, orbiculares del ojo y de la boca, cigomáticos, platisma), además del estapedio, el vientre posterior del digástrico y el estilohioideo.', piel: 'Una pequeña zona de la oreja y del conducto auditivo; además lleva el gusto de los dos tercios anteriores de la lengua.', clinica: 'En la parálisis de Bell la mitad de la cara queda caída: de ese lado no se puede cerrar el ojo, levantar la ceja ni sonreír.', a: ['a_carotida_externa'] });
  add('nervio', 'n_vago', 'Nervio vago (X par craneal)', 'El nervio craneal más largo: baja desde el cráneo hasta el abdomen y es la vía principal del sistema parasimpático, que regula el corazón, los pulmones y la digestión.', { raices: 'Bulbo raquídeo; sale del cráneo por el agujero yugular.', recorrido: 'Baja por el cuello dentro de la vaina carotídea, entre la carótida y la yugular interna; en el tórax pasa por detrás de la raíz del pulmón, forma el plexo esofágico y entra en el abdomen junto al esófago como troncos vagales anterior y posterior.', inerva: 'Músculos de la faringe, del paladar blando y de la laringe (por el nervio laríngeo recurrente); además, el músculo liso y las glándulas de los bronquios y del tubo digestivo, y frena el corazón.', piel: 'Una pequeña zona de la oreja y del conducto auditivo externo.', clinica: 'Su estimulación brusca (por dolor, miedo o al ver sangre) puede bajar la frecuencia cardíaca y la presión y causar un desmayo (síncope vasovagal).', a: ['a_carotida_comun', 'a_carotida_interna'] });
  add('nervio', 'n_accesorio', 'Nervio accesorio (XI par craneal)', 'Nervio motor que mueve el esternocleidomastoideo y el trapecio.', { raices: 'Raíz espinal de los primeros segmentos cervicales de la médula (C1–C5), que sube al cráneo por el agujero magno.', recorrido: 'Sale del cráneo por el agujero yugular, pasa por debajo del esternocleidomastoideo (al que inerva) y cruza en diagonal, muy superficial, el triángulo posterior del cuello hasta el trapecio.', inerva: 'Esternocleidomastoideo y trapecio.', clinica: 'Por ser tan superficial en el cuello puede lesionarse en cirugías o biopsias de ganglios: el hombro cae y cuesta levantar el brazo por encima de la cabeza.' });
  add('nervio', 'n_frenico', 'Nervio frénico', 'Nervio que mueve el diafragma, el principal músculo de la respiración.', { raices: 'C3, C4 y C5 (sobre todo C4), del plexo cervical.', recorrido: 'Baja por el cuello sobre el músculo escaleno anterior, entra en el tórax entre la arteria y la vena subclavias y desciende a los lados del pericardio, por delante de la raíz del pulmón, hasta el diafragma.', inerva: 'Diafragma, del que es el único nervio motor.', piel: 'No inerva piel, pero lleva la sensibilidad del pericardio, de la pleura mediastínica y diafragmática y del peritoneo bajo el diafragma.', clinica: 'La irritación del diafragma (por sangre o pus bajo él) se siente como dolor en el hombro, porque comparte las raíces C3–C5 con la piel de esa zona.', a: ['a_toracica_interna', 'a_subclavia'] });
  add('nervio', 'plexo_braquial', 'Plexo braquial', 'Red de nervios que nace en el cuello y da todos los nervios del miembro superior.', { raices: 'Ramos anteriores de C5, C6, C7, C8 y T1.', recorrido: 'Las raíces pasan entre los escalenos anterior y medio y forman tres troncos (superior, medio e inferior) sobre la primera costilla; detrás de la clavícula se dividen y en la axila forman tres cordones (lateral, posterior y medial) alrededor de la arteria axilar.', inerva: 'Todos los músculos del miembro superior y casi todos los del hombro, a través de nervios como el musculocutáneo, el axilar, el radial, el mediano y el cubital.', piel: 'Casi toda la piel del miembro superior, salvo la parte alta del hombro (plexo cervical) y parte de la axila (nervio intercostobraquial, T2).', clinica: 'Un tirón brusco que separa la cabeza del hombro (caídas de moto, partos difíciles) lesiona su parte superior (C5–C6): el brazo cuelga rotado hacia adentro, como un mesero que pide propina (parálisis de Erb).', a: ['a_subclavia', 'a_axilar'] });
  add('nervio', 'n_dorsal_escapula', 'Nervio dorsal de la escápula', 'Pequeño nervio motor de los músculos que unen la escápula a la columna.', { raices: 'C5, directamente de la raíz del plexo braquial (a veces con fibras de C4).', recorrido: 'Atraviesa el músculo escaleno medio y baja por la espalda junto al borde medial de la escápula, por debajo del elevador de la escápula y de los romboides.', inerva: 'Romboides mayor y menor y, en parte, el elevador de la escápula.', clinica: 'Su lesión debilita los romboides y la escápula de ese lado se separa un poco de la columna.', a: ['a_subclavia'] });
  add('nervio', 'n_supraescapular', 'Nervio supraescapular', 'Nervio que pasa por encima de la escápula hacia dos músculos del manguito rotador.', { raices: 'C5 y C6, del tronco superior del plexo braquial.', recorrido: 'Cruza la parte lateral del cuello, pasa por la escotadura de la escápula bajo el ligamento transverso superior (la arteria pasa por encima) y rodea el cuello de la espina de la escápula hacia la fosa infraespinosa.', inerva: 'Supraespinoso e infraespinoso.', clinica: 'Su atrapamiento, frecuente en deportistas que lanzan o en voleibolistas, debilita la separación y la rotación externa del brazo y adelgaza la parte posterior del hombro.', a: ['a_subclavia'] });
  add('nervio', 'n_toracico_largo', 'Nervio torácico largo', 'Nervio largo y delgado que baja por el costado del tórax hasta el serrato anterior.', { raices: 'C5, C6 y C7 (raíces del plexo braquial).', recorrido: 'Pasa por detrás del plexo braquial y baja por la pared lateral del tórax sobre la cara externa del serrato anterior, donde queda bastante superficial.', inerva: 'Serrato anterior.', clinica: 'Su lesión (en cirugías de la axila o al cargar peso sobre el hombro) produce escápula alada: el borde de la escápula se despega al empujar una pared.', a: ['a_axilar'] });
  add('nervio', 'n_toracodorsal', 'Nervio toracodorsal', 'Nervio del músculo dorsal ancho.', { raices: 'C6, C7 y C8 (cordón posterior del plexo braquial).', recorrido: 'Baja por la pared posterior de la axila junto a la arteria toracodorsal hasta la cara profunda del dorsal ancho.', inerva: 'Dorsal ancho.', clinica: 'El dorsal ancho, con su nervio y su arteria, se usa como colgajo para reconstruir la mama; por eso se protege en la cirugía de la axila.', a: ['a_axilar'] });
  add('nervio', 'n_pectorales', 'Nervios pectorales', 'Dos nervios, lateral y medial, que inervan los músculos pectorales; se nombran por el cordón del que salen, no por su posición.', { raices: 'Lateral: C5–C7 (cordón lateral). Medial: C8–T1 (cordón medial).', recorrido: 'El lateral atraviesa la fascia clavipectoral hacia la cara profunda del pectoral mayor; el medial atraviesa el pectoral menor y llega también al mayor.', inerva: 'Pectoral mayor (los dos nervios) y pectoral menor (sobre todo el medial).', clinica: 'En la cirugía de la mama y de la axila se procura no dañarlos para que el pectoral mayor no se atrofie.', a: ['a_axilar'] });
  add('nervio', 'n_axilar', 'Nervio axilar (circunflejo)', 'Nervio que rodea por detrás el cuello del húmero y mueve el deltoides.', { raices: 'C5 y C6 (cordón posterior del plexo braquial).', recorrido: 'Sale de la axila por el espacio cuadrangular junto a la arteria circunfleja humeral posterior y rodea por detrás el cuello quirúrgico del húmero, bajo el deltoides.', inerva: 'Deltoides y redondo menor.', piel: 'Cara lateral del hombro, sobre la mitad inferior del deltoides.', clinica: 'Se lesiona en las fracturas del cuello quirúrgico del húmero y en las luxaciones del hombro: el deltoides pierde fuerza y se adormece la piel del hombro.', a: ['a_axilar'] });
  add('nervio', 'n_musculocutaneo', 'Nervio musculocutáneo', 'Nervio de los músculos flexores del brazo; termina dando la sensibilidad del borde lateral del antebrazo.', { raices: 'C5, C6 y C7 (cordón lateral del plexo braquial).', recorrido: 'Atraviesa el coracobraquial, baja entre el bíceps y el braquial y, por fuera del tendón del bíceps en el codo, se hace superficial como nervio cutáneo lateral del antebrazo.', inerva: 'Coracobraquial, bíceps braquial y braquial.', piel: 'Cara lateral del antebrazo.', clinica: 'Su lesión aislada es rara; debilita mucho la flexión del codo y la supinación y adormece el borde lateral del antebrazo.', a: ['a_braquial'] });
  add('nervio', 'n_mediano', 'Nervio mediano', 'Nervio principal de la flexión de la muñeca y de los dedos y de los movimientos finos del pulgar.', { raices: 'C6, C7, C8 y T1 (a veces C5), por la unión de los cordones lateral y medial del plexo braquial.', recorrido: 'Baja junto a la arteria braquial por la cara interna del brazo, cruza el codo por dentro del tendón del bíceps, pasa entre las cabezas del pronador redondo, corre bajo el flexor superficial de los dedos y entra en la mano por el túnel carpiano.', inerva: 'Pronadores y casi todos los flexores del antebrazo (salvo el flexor cubital del carpo y la mitad medial del flexor profundo), los músculos de la eminencia tenar y los dos lumbricales laterales.', piel: 'Palma del lado del pulgar y cara palmar del pulgar, el índice, el medio y la mitad del anular, incluido el dorso de sus puntas.', clinica: 'Su compresión en la muñeca (síndrome del túnel carpiano) causa hormigueo nocturno en los tres primeros dedos y debilidad del pulgar.', a: ['a_braquial', 'arcos_palmares'] });
  add('nervio', 'n_cubital', 'Nervio cubital (ulnar)', 'Nervio que pasa por detrás del codo, en el punto que da una sensación de descarga eléctrica al golpearlo, y controla casi todos los músculos pequeños de la mano.', { raices: 'C8 y T1, a veces con fibras de C7 (cordón medial del plexo braquial).', recorrido: 'Baja por la cara interna del brazo, pasa por detrás del epicóndilo medial (surco del nervio cubital), entra en el antebrazo entre las cabezas del flexor cubital del carpo y llega a la mano por el canal de Guyon, junto a la arteria cubital.', inerva: 'Flexor cubital del carpo, mitad medial del flexor profundo de los dedos, eminencia hipotenar, interóseos, los dos lumbricales mediales y el aductor del pulgar.', piel: 'Borde de la mano del lado del meñique, en la palma y en el dorso: el meñique y la mitad del anular.', clinica: 'Su lesión produce la "mano en garra": el anular y el meñique quedan doblados y cuesta separar y juntar los dedos.', a: ['a_cubital', 'a_braquial'] });
  add('nervio', 'n_radial', 'Nervio radial', 'Nervio de los músculos extensores del brazo, del antebrazo y de la muñeca.', { raices: 'C5, C6, C7, C8 y T1 (cordón posterior del plexo braquial).', recorrido: 'Rodea el húmero por detrás en el surco del nervio radial, junto a la arteria braquial profunda; pasa por delante del epicóndilo lateral y se divide en una rama superficial (sensitiva) y una profunda (interósea posterior) que atraviesa el supinador.', inerva: 'Tríceps, ancóneo, braquiorradial, supinador y todos los extensores de la muñeca, de los dedos y del pulgar.', piel: 'Cara posterior del brazo y del antebrazo y dorso de la mano del lado del pulgar.', clinica: 'Una fractura de la diáfisis del húmero o apoyar mucho tiempo el brazo sobre el respaldo de una silla pueden lesionarlo: la muñeca cae y no se puede extender (mano péndula).', a: ['a_braquial_profunda', 'a_radial'] });
  add('nervio', 'n_intercostales', 'Nervios intercostales', 'Ramos anteriores de los nervios torácicos que recorren los espacios entre las costillas; el último (T12), que va bajo la costilla 12, se llama nervio subcostal.', { raices: 'Ramos anteriores de T1 a T11 (T12 forma el nervio subcostal).', recorrido: 'Corren bajo el borde inferior de cada costilla, por debajo de la vena y la arteria intercostales; los inferiores (T7–T11) continúan hacia la pared del abdomen.', inerva: 'Músculos intercostales y, los inferiores, los músculos de la pared del abdomen (rectos y oblicuos).', piel: 'Franjas de piel del tórax y del abdomen (dermatomas): T4 a la altura del pezón y T10 a la del ombligo.', clinica: 'Se bloquean con anestesia bajo el borde de la costilla para aliviar el dolor de las fracturas costales.', a: ['a_intercostales'] });
  add('nervio', 'plexo_lumbar', 'Plexo lumbar', 'Red de nervios que se forma dentro del músculo psoas y da los nervios de la parte baja de la pared del abdomen y de las caras anterior y medial del muslo.', { raices: 'Ramos anteriores de L1 a L4, con participación de T12.', recorrido: 'Se forma en el espesor del psoas mayor; sus ramas salen por su borde lateral (iliohipogástrico, ilioinguinal, cutáneo femoral lateral y femoral), por su borde medial (obturador) y por su cara anterior (genitofemoral).', inerva: 'Músculos bajos de la pared del abdomen, psoas e ilíaco, cuádriceps, sartorio y aductores del muslo.', piel: 'Parte baja del abdomen, ingle, parte de los genitales externos, caras anterior, lateral y medial del muslo y cara medial de la pierna.', clinica: 'Una hemorragia o un absceso en el psoas pueden comprimirlo y causar dolor y debilidad para flexionar la cadera y extender la rodilla.' });
  add('nervio', 'n_iliohipogastrico', 'Nervios iliohipogástrico e ilioinguinal', 'Dos nervios del plexo lumbar que inervan la parte más baja de la pared del abdomen y la piel de la ingle.', { raices: 'L1 (con fibras de T12), del plexo lumbar.', recorrido: 'Salen por el borde lateral del psoas, cruzan por delante del cuadrado lumbar y avanzan entre los músculos de la pared del abdomen; el ilioinguinal recorre el conducto inguinal y sale por el anillo inguinal superficial.', inerva: 'Fibras más bajas del oblicuo interno y del transverso del abdomen.', piel: 'Iliohipogástrico: piel sobre el pubis y la cresta ilíaca. Ilioinguinal: ingle, parte anterior de los genitales externos y parte medial alta del muslo.', clinica: 'El ilioinguinal puede lesionarse o quedar atrapado en la reparación de una hernia inguinal y causar dolor crónico en la ingle.' });
  add('nervio', 'n_cutaneo_femoral_lateral', 'Nervio cutáneo femoral lateral', 'Nervio solo sensitivo de la cara externa del muslo.', { raices: 'L2 y L3, del plexo lumbar.', recorrido: 'Sale por el borde lateral del psoas, cruza el músculo ilíaco y pasa por debajo del ligamento inguinal, muy cerca de la espina ilíaca anterosuperior, hacia la piel del muslo.', inerva: 'Ningún músculo: es exclusivamente sensitivo.', piel: 'Caras anterior y lateral del muslo, hasta la rodilla.', clinica: 'Su compresión bajo el ligamento inguinal (por cinturones o ropa apretada, obesidad o embarazo) causa ardor y adormecimiento en el lado externo del muslo: meralgia parestésica.' });
  add('nervio', 'n_femoral', 'Nervio femoral', 'El nervio más grande del plexo lumbar; extiende la rodilla y da la sensibilidad de la cara anterior del muslo.', { raices: 'L2, L3 y L4 (divisiones posteriores del plexo lumbar).', recorrido: 'Baja entre los músculos psoas e ilíaco, pasa bajo el ligamento inguinal por fuera de la arteria femoral y en el triángulo femoral se abre en abanico en ramas musculares y cutáneas; su rama más larga es el nervio safeno.', inerva: 'Cuádriceps (recto femoral y vastos), sartorio, pectíneo e ilíaco.', piel: 'Caras anterior y medial del muslo y, por el nervio safeno, cara medial de la pierna y del pie.', clinica: 'Su lesión debilita la extensión de la rodilla (la pierna se dobla al apoyarla) y hace desaparecer el reflejo rotuliano.', a: ['a_femoral', 'a_iliaca_externa'] });
  add('nervio', 'n_safeno', 'Nervio safeno', 'La rama sensitiva más larga del nervio femoral; llega hasta el pie.', { raices: 'L3 y L4, a través del nervio femoral.', recorrido: 'Acompaña a la arteria femoral por el conducto aductor, sale por el lado medial de la rodilla y baja junto a la vena safena mayor hasta el borde interno del pie.', inerva: 'Ningún músculo: es exclusivamente sensitivo.', piel: 'Cara medial de la rodilla, de la pierna y del pie, hasta la cabeza del primer metatarsiano.', clinica: 'Puede lesionarse al extraer la vena safena mayor para un bypass, lo que deja adormecido el lado interno de la pierna.', a: ['a_femoral'] });
  add('nervio', 'n_obturador', 'Nervio obturador', 'Nervio de los músculos aductores, que juntan los muslos.', { raices: 'L2, L3 y L4 (divisiones anteriores del plexo lumbar).', recorrido: 'Sale por el borde medial del psoas, baja por la pared lateral de la pelvis y entra en el muslo por el conducto obturador, donde se divide en ramas anterior y posterior alrededor del aductor corto.', inerva: 'Aductores largo, corto y mayor (su parte aductora), grácil, obturador externo y, a veces, el pectíneo.', piel: 'Una zona de la cara medial del muslo.', clinica: 'El dolor de la cadera puede sentirse en la rodilla porque el nervio obturador da ramos a ambas articulaciones.', a: ['a_iliaca_interna'] });
  add('nervio', 'plexo_sacro', 'Plexo sacro', 'Red de nervios de la pared posterior de la pelvis que da los nervios de los glúteos, de la parte posterior del muslo, de la pierna, del pie y del periné.', { raices: 'L4 y L5 (tronco lumbosacro) y S1 a S4.', recorrido: 'Se forma sobre la cara anterior del músculo piriforme; casi todas sus ramas salen de la pelvis por el agujero ciático mayor, por encima o por debajo del piriforme.', inerva: 'Glúteos, rotadores de la cadera, isquiotibiales, todos los músculos de la pierna y del pie y los del suelo pélvico (por el nervio pudendo).', piel: 'Glúteos, cara posterior del muslo, casi toda la pierna y el pie, y el periné.', clinica: 'En el parto se puede bloquear con anestesia el nervio pudendo (S2–S4), una de sus ramas, para aliviar el dolor del periné.', a: ['a_iliaca_interna'] });
  add('nervio', 'n_gluteo_superior', 'Nervio glúteo superior', 'Nervio de los músculos que mantienen la pelvis nivelada al caminar.', { raices: 'L4, L5 y S1 (plexo sacro).', recorrido: 'Sale de la pelvis por el agujero ciático mayor, por encima del piriforme, junto a la arteria glútea superior, y corre entre los glúteos medio y menor.', inerva: 'Glúteo medio, glúteo menor y tensor de la fascia lata.', clinica: 'Su lesión produce el signo de Trendelenburg: al apoyarse en la pierna afectada, la pelvis cae hacia el lado contrario y la marcha se vuelve oscilante.', a: ['a_iliaca_interna'] });
  add('nervio', 'n_gluteo_inferior', 'Nervio glúteo inferior', 'Nervio del glúteo mayor, el gran extensor de la cadera.', { raices: 'L5, S1 y S2 (plexo sacro).', recorrido: 'Sale de la pelvis por el agujero ciático mayor, por debajo del piriforme, junto a la arteria glútea inferior, y se ramifica en la cara profunda del glúteo mayor.', inerva: 'Glúteo mayor.', clinica: 'Su lesión debilita el glúteo mayor: cuesta levantarse de una silla, subir escaleras o enderezar el tronco al estar inclinado.', a: ['a_iliaca_interna'] });
  add('nervio', 'n_ciatico', 'Nervio ciático', 'El nervio más grueso y largo del cuerpo; en realidad son dos nervios, tibial y peroneo común, unidos en una misma vaina.', { raices: 'L4, L5, S1, S2 y S3 (plexo sacro).', recorrido: 'Sale de la pelvis por el agujero ciático mayor, por debajo del piriforme; baja por la nalga entre el trocánter mayor y la tuberosidad isquiática y recorre la parte posterior del muslo bajo los isquiotibiales, hasta dividirse por encima de la rodilla en tibial y peroneo común.', inerva: 'Isquiotibiales (bíceps femoral, semitendinoso y semimembranoso) y parte del aductor mayor; por sus ramas, todos los músculos de la pierna y del pie.', piel: 'Por sus ramas, casi toda la pierna y el pie, salvo el lado medial (nervio safeno).', clinica: 'La compresión de sus raíces, casi siempre L5 o S1 por una hernia de disco, causa ciática: un dolor que baja desde la nalga por la parte posterior de la pierna.', a: ['a_iliaca_interna'] });
  add('nervio', 'n_tibial', 'Nervio tibial', 'Rama medial del nervio ciático; mueve los músculos de la pantorrilla y de la planta del pie.', { raices: 'L4, L5, S1, S2 y S3 (divisiones anteriores del plexo sacro).', recorrido: 'Cruza la fosa poplítea por el centro (es su estructura más superficial), baja entre los músculos profundos de la pantorrilla junto a la arteria tibial posterior y pasa por detrás del maléolo medial, bajo el retináculo flexor (túnel tarsiano), donde se divide en nervios plantares medial y lateral.', inerva: 'Gastrocnemio, sóleo, plantar, poplíteo, tibial posterior y flexores largos de los dedos y del dedo gordo; por los nervios plantares, los músculos de la planta.', piel: 'Talón y planta del pie y, junto con el peroneo común (a través del nervio sural), la parte posterolateral de la pierna y el borde lateral del pie.', clinica: 'Su compresión detrás del maléolo medial (síndrome del túnel tarsiano) causa ardor y adormecimiento en la planta del pie.', a: ['a_poplitea', 'a_tibial_posterior'] });
  add('nervio', 'n_peroneo_comun', 'Nervio peroneo (fibular) común', 'Rama lateral del nervio ciático; rodea el cuello del peroné y se divide en peroneo superficial y profundo.', { raices: 'L4, L5, S1 y S2 (divisiones posteriores del plexo sacro).', recorrido: 'Baja por el borde lateral de la fosa poplítea siguiendo el tendón del bíceps femoral y rodea el cuello del peroné justo bajo la piel, donde se divide en sus dos ramas terminales.', inerva: 'Cabeza corta del bíceps femoral (cuando aún va dentro del ciático) y, por sus ramas, los músculos anteriores y laterales de la pierna y el extensor corto de los dedos.', piel: 'Cara lateral de la pierna y, por sus ramas, el dorso del pie.', clinica: 'Es el nervio del miembro inferior que más se lesiona: un golpe o un yeso apretado en el cuello del peroné causan pie caído y marcha en estepaje.', a: ['a_poplitea'] });
  add('nervio', 'n_peroneo_superficial', 'Nervio peroneo (fibular) superficial', 'Rama del peroneo común que mueve los músculos peroneos y da la sensibilidad de casi todo el dorso del pie.', { raices: 'Principalmente L5 y S1, a través del nervio peroneo común.', recorrido: 'Baja entre los músculos peroneos y el extensor largo de los dedos y, en el tercio inferior de la pierna, atraviesa la fascia y se hace subcutáneo hacia el dorso del pie.', inerva: 'Peroneo largo y peroneo corto.', piel: 'Parte baja de la cara lateral de la pierna y casi todo el dorso del pie, salvo el espacio entre el primer y el segundo dedo.', clinica: 'Su lesión debilita la eversión del pie (girar la planta hacia afuera) y adormece el dorso del pie.' });
  add('nervio', 'n_peroneo_profundo', 'Nervio peroneo (fibular) profundo', 'Rama del peroneo común que levanta el pie y los dedos.', { raices: 'Principalmente L4 y L5, a través del nervio peroneo común.', recorrido: 'Atraviesa el extensor largo de los dedos, baja por delante de la membrana interósea junto a la arteria tibial anterior y continúa en el dorso del pie junto a la arteria dorsal del pie.', inerva: 'Tibial anterior, extensor largo de los dedos, extensor largo del dedo gordo, peroneo tercero y extensor corto de los dedos.', piel: 'Solo el espacio de piel entre el dedo gordo y el segundo dedo.', clinica: 'Si se lesiona no se puede levantar el pie (pie caído) y se adormece el espacio entre el primer y el segundo dedo.', a: ['a_tibial_anterior', 'a_dorsal_pie'] });
  add('nervio', 'n_sural', 'Nervio sural', 'Nervio sensitivo de la parte posterior de la pantorrilla y del borde externo del pie.', { raices: 'Principalmente S1; se forma por la unión de ramos del nervio tibial y del peroneo común.', recorrido: 'Baja entre las cabezas del gastrocnemio junto a la vena safena menor y pasa por detrás del maléolo lateral hacia el borde lateral del pie.', inerva: 'Ningún músculo: es exclusivamente sensitivo.', piel: 'Parte posterolateral de la pierna, lado externo del talón y borde lateral del pie hasta el dedo pequeño.', clinica: 'Se usa con frecuencia para biopsias de nervio y como injerto para reparar otros nervios, porque su pérdida solo deja una pequeña zona sin sensibilidad.' });
  add('nervio', 'n_plantares', 'Nervios plantares', 'Ramas terminales del nervio tibial, medial y lateral, que inervan la planta del pie; su reparto recuerda al de los nervios mediano y cubital en la mano.', { raices: 'L4 a S3, a través del nervio tibial.', recorrido: 'Nacen bajo el retináculo flexor, detrás del maléolo medial, pasan bajo el abductor del dedo gordo y recorren la planta: el medial hacia el dedo gordo y el lateral hacia el dedo pequeño.', inerva: 'Medial: abductor y flexor corto del dedo gordo, flexor corto de los dedos y primer lumbrical. Lateral: el resto de los músculos de la planta, incluidos los interóseos y el aductor del dedo gordo.', piel: 'Planta del pie: el medial, la parte interna y los tres dedos y medio mediales; el lateral, la parte externa y el dedo y medio laterales.', clinica: 'La irritación de un nervio digital plantar entre las cabezas de los metatarsianos (neuroma de Morton) causa dolor quemante, sobre todo entre el tercer y el cuarto dedo.', a: ['a_plantares', 'a_tibial_posterior'] });
}
